const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.1",
  "engineVersion": "d1b3f377ca835d73fd50954a5e22128b9ebdd6b8",
  "activeProvider": "postgresql",
  "inlineSchema": "// Agent Space — Prisma schema\n// Source of truth: docs/Product_Specification.md (v1.2)\n//\n// Conventions\n// - Table names are snake_case plural via @@map; columns are snake_case.\n// - Primary keys are UUID strings. Foreign keys are named <relation>_id.\n// - Soft deletes use deleted_at (30-day restore window for skills, artifacts, files, credentials).\n// - Settings that are \"the source of truth\" live here as typed columns; Redis only holds counters/caches.\n// - Secret VALUES are never stored here (only Secret Manager resource names and masked hints). See §8.7.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// =====================================================================\n// ENUMS — platform / auth\n// =====================================================================\n\nenum AuthRole {\n  USER\n  ADMIN\n  SUPER_ADMIN\n  SUPPORT\n}\n\nenum AuthProvider {\n  EMAIL\n  GOOGLE\n  MICROSOFT\n  APPLE\n}\n\nenum DocumentType {\n  LOGO\n  BANNER\n  IMAGE\n  VIDEO\n  AUDIO\n  PDF\n  DOCUMENT\n  OTHER\n}\n\nenum Platform {\n  WEB\n  DESKTOP\n  ANDROID\n}\n\nenum PushProvider {\n  WEBPUSH\n  FCM\n}\n\nenum DeviceToolKind {\n  LOCAL_FILES\n  SCREEN\n  LOCAL_TOOL_SERVERS\n  CLIPBOARD\n  OPEN\n  CONTROL_COMPUTER\n  CAMERA_SCANNER\n  CONTACTS\n  SEND_VIA_APPS\n  DEVICE_CALENDAR\n  LOCATION\n}\n\nenum DeviceToolPermission {\n  ASK_EACH_TIME\n  ALWAYS_ALLOW\n  NEVER\n}\n\n// =====================================================================\n// ENUMS — personal settings (§13.2)\n// =====================================================================\n\nenum Theme {\n  SYSTEM\n  LIGHT\n  DARK\n}\n\n/// Colour preset a member picks per organisation (§13.2 Appearance). Light/dark mode is chosen separately.\nenum ColorTheme {\n  NEUTRAL\n  GRAPE\n  OCEAN\n  SKY\n  TEAL\n  FOREST\n  LIME\n  SUNSET\n  AMBER\n  ROSE\n  CRIMSON\n  LAVENDER\n  SLATE\n}\n\nenum TextSize {\n  SMALL\n  MEDIUM\n  LARGE\n}\n\nenum LayoutDensity {\n  COMFORTABLE\n  COMPACT\n}\n\nenum AppLanguage {\n  EN\n  EL\n}\n\nenum ReplyLanguage {\n  SAME_AS_MESSAGE\n  ALWAYS_EN\n  ALWAYS_EL\n}\n\nenum TimeFormat {\n  REGION\n  H24\n  H12\n}\n\nenum ReplyLength {\n  SHORT\n  BALANCED\n  DETAILED\n}\n\nenum ReplyTone {\n  CASUAL\n  FRIENDLY_PROFESSIONAL\n  FORMAL\n}\n\nenum ReplyFormatting {\n  MIXED\n  MOSTLY_BULLETS\n  MOSTLY_PARAGRAPHS\n}\n\nenum EmojiUsage {\n  NONE\n  OCCASIONALLY\n  OFTEN\n}\n\nenum ClarifyingQuestions {\n  ASK_MORE_OFTEN\n  BALANCED\n  ASSUME_AND_PROCEED\n}\n\nenum ActivityStepsDisplay {\n  COLLAPSED\n  EXPANDED\n  HIDDEN\n}\n\nenum ArtifactOpenMode {\n  SIDE_PANEL\n  FULL_SCREEN\n  NEW_TAB\n}\n\nenum SendWithKey {\n  ENTER\n  CTRL_ENTER\n}\n\nenum GroupReplyMode {\n  MOST_RELEVANT\n  ONLY_WHEN_MENTIONED\n}\n\nenum ReadAloudMode {\n  OFF\n  VOICE_MESSAGES_ONLY\n  ALWAYS\n}\n\nenum SpeakingSpeed {\n  SLOWER\n  NORMAL\n  FASTER\n}\n\nenum VoiceInputMode {\n  HANDS_FREE\n  PUSH_TO_TALK\n}\n\nenum ApprovalLevel {\n  ALWAYS_ASK\n  IMPORTANT_ACTIONS\n  DONT_ASK\n}\n\nenum ApprovalTimeout {\n  KEEP_WAITING\n  CANCEL_AFTER_1H\n  CANCEL_AFTER_24H\n}\n\nenum ApprovalChannel {\n  IN_APP_PUSH\n  IN_APP_PUSH_EMAIL\n}\n\nenum TaskCheckIn {\n  MIN_15\n  HOUR_1\n  HOUR_4\n  NEVER\n}\n\nenum AutomationResultsDestination {\n  BOT_CONVERSATION\n  EMAIL\n  BOTH\n}\n\nenum ConversationRetention {\n  NEVER\n  DAYS_30\n  DAYS_90\n  YEAR_1\n}\n\n// =====================================================================\n// ENUMS — organisation settings (§13.4)\n// =====================================================================\n\nenum OrganizationRole {\n  OWNER\n  ADMIN\n  MEMBER\n}\n\nenum InvitationStatus {\n  PENDING\n  ACCEPTED\n  CANCELLED\n  EXPIRED\n}\n\nenum InvitationExpiry {\n  DAY_1\n  DAY_3\n  DAY_7\n  DAY_30\n}\n\nenum WhoCan {\n  EVERYONE\n  OWNERS_ADMINS\n}\n\nenum ModelPolicy {\n  ALL_MODELS\n  APPROVED_LIST\n}\n\nenum ServicePolicy {\n  ALL\n  APPROVED_LIST\n  BLOCK_LIST\n}\n\nenum InteractiveRepliesMode {\n  BLOCKS_AND_MINI_APPS\n  BLOCKS_ONLY\n  OFF\n}\n\nenum IdlePause {\n  MIN_5\n  MIN_15\n  MIN_30\n}\n\nenum MaxSession {\n  HOUR_1\n  HOUR_4\n  HOUR_24\n}\n\n/// What happens when an organisation approval timeout is reached.\nenum ApprovalTimeoutAction {\n  CANCEL\n  APPROVE\n}\n\nenum MinApprovalLevel {\n  NONE\n  IMPORTANT_ACTIONS\n  ALWAYS_ASK\n}\n\nenum PublicLinkPolicy {\n  EVERYONE\n  OWNERS_ADMINS\n  OFF\n}\n\nenum PublicLinkLifetime {\n  NO_LIMIT\n  DAYS_7\n  DAYS_30\n  DAYS_90\n}\n\nenum ArtifactDesignDefault {\n  ORGANIZATION_BRAND\n  NEUTRAL\n}\n\nenum VoiceSessionLength {\n  MIN_15\n  MIN_30\n  MIN_60\n}\n\nenum ScheduleFrequency {\n  EVERY_15_MIN\n  EVERY_HOUR\n  DAILY\n}\n\nenum LimitReachedAction {\n  PAUSE_AND_NOTIFY\n  SWITCH_TO_CHEAPER_MODEL\n  NOTIFY_ONLY\n}\n\nenum OrgConversationRetention {\n  FOREVER\n  YEAR_1\n  DAYS_90\n  DAYS_30\n}\n\nenum ComputerRetention {\n  DAYS_30\n  DAYS_90\n  YEAR_1\n}\n\nenum MaxFileSize {\n  MB_25\n  MB_50\n  MB_100\n}\n\nenum SessionInactivity {\n  DAYS_30\n  DAYS_7\n  DAY_1\n}\n\nenum BiometricApprovalScope {\n  ALL_APPROVALS\n  EXTERNAL_EMAILS\n  DELETING_DATA\n}\n\n// =====================================================================\n// ENUMS — bots (§6, §13.3)\n// =====================================================================\n\nenum BotVisibility {\n  PRIVATE\n  ORGANIZATION\n}\n\nenum BotEditPolicy {\n  CREATOR_ONLY\n  CREATOR_AND_ADMINS\n}\n\nenum Creativity {\n  PRECISE\n  BALANCED\n  CREATIVE\n}\n\nenum BotClarifyingQuestions {\n  USER_PREFERENCE\n  ASK_MORE_OFTEN\n  ASSUME_AND_PROCEED\n}\n\nenum BotGroupResponse {\n  WHEN_RELEVANT_OR_MENTIONED\n  ONLY_WHEN_MENTIONED\n}\n\nenum SpokenReplyStyle {\n  SHORT_CONVERSATIONAL\n  DETAILED\n}\n\nenum MemoryScope {\n  PER_USER\n  SHARED\n}\n\nenum MaxTaskDuration {\n  MIN_15\n  HOUR_1\n  HOUR_4\n  HOUR_24\n}\n\nenum ActionType {\n  SEND_MESSAGE\n  POST_PUBLICLY\n  EDIT_RECORDS\n  DELETE_DATA\n  PURCHASE_PAYMENT\n  SHARE_FILES\n  ENTER_PASSWORD\n  EXTERNAL_EMAIL\n  CONSULT_SENSITIVE_BOT\n  OTHER\n}\n\nenum ApprovalOverride {\n  ALWAYS_ASK\n  DONT_ASK\n}\n\n/// Per-tool permission a user sets for a connected service. AUTO_REVIEW (the default) follows the bot's approval level.\nenum ToolPermission {\n  ALWAYS_ALLOW\n  AUTO_REVIEW\n  NEEDS_APPROVAL\n  BLOCKED\n}\n\nenum KnowledgeScope {\n  BOT\n  ORGANIZATION\n}\n\nenum KnowledgeKind {\n  FILE\n  LINK\n  TEXT\n}\n\n/// Indexing state of a knowledge item: text extraction (incl. OCR) + embeddings, done by the `knowledge` queue.\nenum KnowledgeStatus {\n  PROCESSING\n  READY\n  FAILED\n}\n\nenum MemoryKind {\n  BOT_USER\n  BOT_SHARED\n  ORGANIZATION\n}\n\nenum ModelCostTier {\n  LOW\n  MEDIUM\n  HIGH\n}\n\n// =====================================================================\n// ENUMS — conversations, runs, approvals (§7, §10, §11)\n// =====================================================================\n\nenum ConversationShareMode {\n  /// Viewers see only the messages that existed when the link was made (or last refreshed).\n  SNAPSHOT\n  /// Viewers also see new messages as they arrive.\n  LIVE\n}\n\nenum ConversationType {\n  DIRECT\n  SHARED_BOT\n  GROUP\n}\n\nenum MessageAuthorType {\n  USER\n  BOT\n  SYSTEM\n}\n\nenum MessageSource {\n  TEXT\n  VOICE\n  AUTOMATION\n  BOT\n  EMAIL\n  SLACK\n  WHATSAPP\n}\n\n/// Outside places members can talk to their bots from (§16 Message from anywhere).\nenum ExternalChannel {\n  EMAIL\n  SLACK\n  WHATSAPP\n}\n\nenum ChannelLinkStatus {\n  PENDING\n  ACTIVE\n}\n\nenum MessageStatus {\n  PENDING\n  STREAMING\n  COMPLETED\n  FAILED\n  STOPPED\n}\n\nenum RunType {\n  CHAT_REPLY\n  TASK\n  AUTOMATION_RUN\n  BOT_TO_BOT\n}\n\nenum RunStatus {\n  QUEUED\n  RUNNING\n  WAITING_APPROVAL\n  WAITING_INPUT\n  WAITING_DEVICE\n  WAITING_COMPUTER\n  COMPLETED\n  FAILED\n  STOPPED\n}\n\nenum RunStepType {\n  THINKING\n  TOOL_CALL\n  CONNECTION_CALL\n  COMPUTER_ACTION\n  DEVICE_TOOL\n  SKILL_USED\n  BOT_CONSULTED\n  FILE_WRITE\n  ARTIFACT_EDIT\n  APPROVAL\n  MESSAGE\n  ERROR\n}\n\nenum RunStepStatus {\n  RUNNING\n  COMPLETED\n  FAILED\n  SKIPPED\n}\n\nenum ApprovalStatus {\n  PENDING\n  APPROVED\n  EDITED_APPROVED\n  REJECTED\n  CANCELLED\n  EXPIRED\n}\n\nenum VoiceSessionEndReason {\n  USER_EXIT\n  SILENCE\n  MAX_LENGTH\n  CONNECTION_LOST\n  USAGE_LIMIT\n  ERROR\n}\n\n// =====================================================================\n// ENUMS — skills, artifacts (§6.7, §7.5)\n// =====================================================================\n\nenum SharingLevel {\n  PRIVATE\n  SPECIFIC_MEMBERS\n  ORGANIZATION\n}\n\nenum SkillRole {\n  OWNER\n  EDITOR\n  USER\n}\n\nenum ArtifactType {\n  WEB_APP\n  DASHBOARD\n  PAGE\n  DOCUMENT\n  PRESENTATION\n  DIAGRAM\n  FORM\n  TOOL\n  GAME\n  OTHER\n}\n\nenum ArtifactSharingLevel {\n  PRIVATE\n  SPECIFIC_MEMBERS\n  ORGANIZATION\n  PUBLIC_LINK\n}\n\nenum ArtifactRole {\n  OWNER\n  EDITOR\n  COMMENTER\n  VIEWER\n}\n\nenum ArtifactVersionStatus {\n  DRAFT\n  PUBLISHED\n}\n\nenum ArtifactReportStatus {\n  OPEN\n  REVIEWED\n  TAKEN_DOWN\n  DISMISSED\n}\n\n// =====================================================================\n// ENUMS — connections, credentials, tool servers (§8)\n// =====================================================================\n\nenum ConnectionKind {\n  COMPOSIO\n  API_KEY\n  MCP\n}\n\nenum Visibility {\n  PRIVATE\n  SHARED\n}\n\nenum ConnectionStatus {\n  ACTIVE\n  NEEDS_RECONNECTING\n  ERROR\n}\n\nenum CredentialOwnerType {\n  USER\n  ORGANIZATION\n}\n\nenum CredentialKind {\n  MCP_OAUTH\n  MCP_TOKEN\n  API_KEY\n  /// Username + password (+ optional two-step secret) the bot types into one website on its cloud computer (§9.4).\n  WEBSITE_LOGIN\n  /// §16 Password manager connection (1Password Connect): server address + access token; logins are looked up per website at sign-in time.\n  PASSWORD_MANAGER\n}\n\nenum CredentialStatus {\n  ACTIVE\n  NOT_WORKING\n  EXPIRED\n  NEEDS_RECONNECTING\n}\n\nenum CredentialEventType {\n  CREATED\n  REPLACED\n  RENAMED\n  SHARED\n  MADE_PRIVATE\n  BOTS_CHANGED\n  TESTED\n  USED\n  DELETED\n}\n\nenum ToolServerAuthKind {\n  NONE\n  OAUTH\n  TOKEN\n}\n\nenum ToolServerStatus {\n  ACTIVE\n  NEEDS_RECONNECTING\n  ERROR\n}\n\nenum ToolRunsOn {\n  SERVER\n  DEVICE\n}\n\n// =====================================================================\n// ENUMS — files, cloud computers (§7.7, §9)\n// =====================================================================\n\nenum FileBucket {\n  FILES\n  ARTIFACTS\n  REPLAYS\n  EXPORTS\n  PUBLIC\n}\n\nenum FileArea {\n  CHAT\n  GENERATED\n  KNOWLEDGE\n  SKILLS\n  COMPUTER\n  ARTIFACTS\n  REPLAYS\n  EXPORTS\n  AUTOMATIONS\n  PUBLIC\n}\n\nenum FileStatus {\n  PENDING\n  READY\n  FAILED\n}\n\nenum CloudComputerStatus {\n  OFF\n  STARTING\n  RUNNING\n  PAUSED\n  ERROR\n}\n\nenum ComputerSessionKind {\n  BOT_RUN\n  USER_EXPLORE\n}\n\nenum TransferDirection {\n  TO_COMPUTER\n  FROM_COMPUTER\n}\n\nenum TransferSourceKind {\n  STORED_FILE\n  COMPOSIO\n  API_KEY_CONNECTION\n  PUBLIC_URL\n  CHAT\n  STORAGE\n  CONNECTED_SERVICE\n}\n\n// =====================================================================\n// ENUMS — automations, notifications, usage, billing, activity\n// =====================================================================\n\nenum AutomationTriggerKind {\n  SCHEDULE\n  COMPOSIO_TRIGGER\n  PLACE\n}\n\nenum AutomationStatus {\n  ACTIVE\n  PAUSED\n  NEEDS_ATTENTION\n}\n\nenum AutomationRunStatus {\n  QUEUED\n  RUNNING\n  WAITING_APPROVAL\n  SUCCEEDED\n  FAILED\n  SKIPPED\n  STOPPED\n}\n\nenum ResultDestinationKind {\n  CONVERSATION\n  EMAIL\n  CONNECTION\n}\n\nenum NotificationEvent {\n  NEW_MESSAGE\n  MENTION\n  APPROVAL_NEEDED\n  TASK_FINISHED\n  TASK_FAILED\n  CONNECTION_NEEDS_RECONNECTING\n  SECRET_NOT_WORKING\n  INVITATION_RECEIVED\n  AUTOMATION_RESULT\n  AUTOMATION_PAUSED\n  ARTIFACT_SHARED\n  ARTIFACT_COMMENT\n  ARTIFACT_EDITED\n  SKILL_SHARED\n  SKILL_CHANGED\n  TAKE_CONTROL_NEEDED\n  USAGE_LIMIT\n  MODEL_CHANGED\n  EXPORT_READY\n  SYSTEM\n}\n\nenum NotificationChannel {\n  IN_APP\n  PUSH\n  EMAIL\n}\n\nenum DeliveryStatus {\n  QUEUED\n  SENT\n  FAILED\n  SKIPPED\n}\n\nenum UsageKind {\n  MODEL_TOKENS\n  COMPUTER_MINUTES\n  VOICE_MINUTES\n  STORAGE_BYTES\n  ARTIFACT_AI\n}\n\nenum UsageLimitScope {\n  ORGANIZATION\n  MEMBER\n  BOT\n}\n\nenum PlanTier {\n  FREE\n  STARTER\n  TEAM\n  BUSINESS\n  ENTERPRISE\n}\n\nenum SubscriptionStatus {\n  TRIALING\n  ACTIVE\n  PAST_DUE\n  CANCELLED\n  PAUSED\n}\n\nenum InvoiceStatus {\n  DRAFT\n  OPEN\n  PAID\n  VOID\n  UNCOLLECTIBLE\n}\n\nenum ActorType {\n  USER\n  BOT\n  SYSTEM\n}\n\nenum ExportKind {\n  USER_DATA\n  ACTIVITY_HISTORY\n  SKILL\n}\n\nenum ExportStatus {\n  QUEUED\n  RUNNING\n  READY\n  FAILED\n  EXPIRED\n}\n\n// =====================================================================\n// USERS, AUTH, DEVICES\n// =====================================================================\n\nmodel User {\n  id                 String    @id @default(uuid())\n  email              String    @unique\n  phone              String?   @unique\n  password           String\n  role               AuthRole  @default(USER)\n  name               String?\n  avatar_file_id     String?   @unique\n  job_title          String?\n  about_me           String?\n  timezone           String    @default(\"UTC\")\n  working_hours      Json? // { days: [1..5], start: \"09:00\", end: \"18:00\" }\n  email_verified_at  DateTime?\n  two_factor_enabled Boolean   @default(false)\n  two_factor_secret  String?\n  last_active_at     DateTime?\n  deleted_at         DateTime?\n  created_at         DateTime  @default(now())\n  updated_at         DateTime  @updatedAt\n\n  avatar                  File?                     @relation(\"UserAvatar\", fields: [avatar_file_id], references: [id], onDelete: SetNull)\n  settings                UserSettings?\n  identities              AuthIdentity[]\n  sessions                Session[]\n  password_reset_tokens   PasswordResetToken[]\n  devices                 Device[]\n  device_places           DevicePlace[]\n  notification_prefs      NotificationPreference[]\n  memberships             OrganizationMember[]\n  owned_organizations     Organization[]            @relation(\"OrganizationCreator\")\n  invitations_sent        Invitation[]              @relation(\"InvitationInviter\")\n  invitations_accepted    Invitation[]              @relation(\"InvitationAcceptor\")\n  bots_created            Bot[]                     @relation(\"BotCreator\")\n  bot_connection_defaults UserServiceDefault[]\n  tool_permissions        UserToolPermission[]\n  conversations_created   Conversation[]            @relation(\"ConversationCreator\")\n  conversation_shares     ConversationShare[]\n  conversation_folders    ConversationFolder[]\n  participations          ConversationParticipant[]\n  messages                Message[]                 @relation(\"MessageUserAuthor\")\n  pinned_messages         Message[]                 @relation(\"MessagePinnedBy\")\n  reactions               MessageReaction[]\n  saved_widgets           SavedWidget[]\n  artifact_data_grants    ArtifactDataGrant[]\n  runs                    Run[]                     @relation(\"RunUser\")\n  approvals_resolved      Approval[]                @relation(\"ApprovalResolver\")\n  voice_sessions          VoiceSession[]\n  memories                Memory[]\n  skills_owned            Skill[]                   @relation(\"SkillOwner\")\n  skill_versions          SkillVersion[]\n  skill_shares            SkillShare[]\n  artifacts_owned         Artifact[]                @relation(\"ArtifactOwner\")\n  artifact_versions       ArtifactVersion[]\n  artifact_shares         ArtifactShare[]\n  artifact_comments       ArtifactComment[]\n  artifact_reports        ArtifactReport[]\n  connections             Connection[]              @relation(\"ConnectionOwner\")\n  credentials             Credential[]              @relation(\"CredentialOwner\")\n  credential_events       CredentialEvent[]\n  tool_servers            ToolServer[]              @relation(\"ToolServerOwner\")\n  files_uploaded          File[]                    @relation(\"FileUploader\")\n  computer_sessions       ComputerSession[]\n  automations             Automation[]\n  notifications           Notification[]\n  usage_charges           UsageCharge[]\n  activity_logs           ActivityLog[]\n  data_exports            DataExport[]\n  knowledge_items         KnowledgeItem[]\n  knowledge_links         KnowledgeLink[]\n\n  channel_links ChannelLink[]\n\n  @@index([email])\n  @@index([phone])\n  @@index([deleted_at])\n  @@map(\"users\")\n}\n\nmodel AuthIdentity {\n  id               String       @id @default(uuid())\n  user_id          String\n  provider         AuthProvider\n  provider_user_id String\n  provider_email   String?\n  created_at       DateTime     @default(now())\n  updated_at       DateTime     @updatedAt\n\n  user User @relation(fields: [user_id], references: [id], onDelete: Cascade)\n\n  @@unique([provider, provider_user_id])\n  @@index([user_id])\n  @@map(\"auth_identities\")\n}\n\nmodel Session {\n  id                 String    @id @default(uuid())\n  user_id            String\n  device_id          String?\n  refresh_token_hash String    @unique\n  ip_address         String?\n  user_agent         String?\n  expires_at         DateTime\n  last_used_at       DateTime  @default(now())\n  revoked_at         DateTime?\n  created_at         DateTime  @default(now())\n\n  user   User    @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  device Device? @relation(fields: [device_id], references: [id], onDelete: SetNull)\n\n  @@index([user_id])\n  @@index([device_id])\n  @@index([expires_at])\n  @@map(\"sessions\")\n}\n\nmodel PasswordResetToken {\n  id         String    @id @default(uuid())\n  token_hash String    @unique\n  user_uuid  String\n  expires_at DateTime\n  used_at    DateTime?\n  created_at DateTime  @default(now())\n\n  user User @relation(fields: [user_uuid], references: [id], onDelete: Cascade)\n\n  @@index([user_uuid])\n  @@index([expires_at])\n  @@map(\"password_reset_tokens\")\n}\n\n/// Legacy upload record kept for backwards compatibility with existing code. New files use `File`.\nmodel Document {\n  id         String       @id @default(uuid())\n  user_uuid  String\n  filename   String\n  mimetype   String\n  size       Int\n  url        String\n  path       String\n  type       DocumentType @default(LOGO)\n  created_at DateTime     @default(now())\n\n  @@index([user_uuid])\n  @@map(\"documents\")\n}\n\n/// §14.1 — one row per signed-in device (web browser, desktop app, phone).\nmodel Device {\n  id                       String        @id @default(uuid())\n  user_id                  String\n  name                     String\n  platform                 Platform\n  app_version              String?\n  push_provider            PushProvider?\n  push_token               String?\n  capabilities             String[]      @default([])\n  is_online                Boolean       @default(false)\n  last_seen_at             DateTime      @default(now())\n  // Desktop-only (§13.2 Devices)\n  allowed_folders          String[]      @default([])\n  /// Extra apps bots may never control on this computer (§14.3), on top of the built-in blocked list.\n  blocked_apps             String[]      @default([])\n  launch_at_startup        Boolean       @default(true)\n  quick_ask_shortcut       String?\n  // Mobile-only\n  approve_from_lock_screen Boolean       @default(true)\n  created_at               DateTime      @default(now())\n  updated_at               DateTime      @updatedAt\n\n  user                    User                   @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  sessions                Session[]\n  tool_permissions        DeviceToolSetting[]\n  local_tool_servers      LocalToolServer[]\n  run_steps               RunStep[]\n  notification_deliveries NotificationDelivery[]\n  activity_logs           ActivityLog[]\n\n  @@index([user_id])\n  @@index([push_token])\n  @@map(\"devices\")\n}\n\nmodel DeviceToolSetting {\n  id         String               @id @default(uuid())\n  device_id  String\n  tool       DeviceToolKind\n  permission DeviceToolPermission @default(ASK_EACH_TIME)\n  updated_at DateTime             @updatedAt\n\n  device Device @relation(fields: [device_id], references: [id], onDelete: Cascade)\n\n  @@unique([device_id, tool])\n  @@map(\"device_tool_settings\")\n}\n\n/// §14.3 — tool servers (MCP) running on the user's own computer. Private to that device.\nmodel LocalToolServer {\n  id         String   @id @default(uuid())\n  device_id  String\n  name       String\n  command    String\n  args       String[] @default([])\n  env_keys   String[] @default([]) // names only, never values\n  enabled    Boolean  @default(true)\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  device Device @relation(fields: [device_id], references: [id], onDelete: Cascade)\n\n  @@index([device_id])\n  @@map(\"local_tool_servers\")\n}\n\n/// §13.2 / §14.3 — saved places for place-based automations (max 20 per user).\nmodel DevicePlace {\n  id            String   @id @default(uuid())\n  user_id       String\n  name          String\n  latitude      Float\n  longitude     Float\n  radius_meters Int      @default(150)\n  created_at    DateTime @default(now())\n  updated_at    DateTime @updatedAt\n\n  user        User         @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  automations Automation[]\n\n  @@index([user_id])\n  @@map(\"device_places\")\n}\n\n// =====================================================================\n// PERSONAL SETTINGS (§13.2)\n// =====================================================================\n\nmodel UserSettings {\n  id      String @id @default(uuid())\n  user_id String @unique\n\n  // Appearance\n  theme          Theme         @default(SYSTEM)\n  text_size      TextSize      @default(MEDIUM)\n  layout_density LayoutDensity @default(COMFORTABLE)\n\n  // Language and region\n  app_language   AppLanguage   @default(EN)\n  reply_language ReplyLanguage @default(SAME_AS_MESSAGE)\n  time_format    TimeFormat    @default(REGION)\n  currency       String? // null = based on region\n  units          String? // \"metric\" | \"imperial\" | null = region\n\n  // How bots reply to me\n  reply_length           ReplyLength          @default(BALANCED)\n  reply_tone             ReplyTone            @default(FRIENDLY_PROFESSIONAL)\n  reply_formatting       ReplyFormatting      @default(MIXED)\n  emoji_usage            EmojiUsage           @default(OCCASIONALLY)\n  show_sources           Boolean              @default(true)\n  suggested_follow_ups   Boolean              @default(true)\n  clarifying_questions   ClarifyingQuestions  @default(BALANCED)\n  proactive_suggestions  Boolean              @default(true)\n  suggest_skills         Boolean              @default(true)\n  activity_steps_display ActivityStepsDisplay @default(COLLAPSED)\n  interactive_replies    Boolean              @default(true)\n\n  // Artifacts\n  artifact_default_sharing ArtifactSharingLevel @default(PRIVATE)\n  artifact_open_mode       ArtifactOpenMode     @default(SIDE_PANEL)\n  artifact_notify_changes  Boolean              @default(true)\n\n  // Chat behaviour\n  default_bot_id         String?\n  send_with              SendWithKey    @default(ENTER)\n  group_reply_mode       GroupReplyMode @default(MOST_RELEVANT)\n  show_typing_indicators Boolean        @default(true)\n\n  // Voice\n  read_aloud           ReadAloudMode  @default(OFF)\n  voice_override       String? // null = use each bot's voice\n  speaking_speed       SpeakingSpeed  @default(NORMAL)\n  auto_send_voice_note Boolean        @default(false)\n  voice_input_mode     VoiceInputMode @default(HANDS_FREE)\n  keep_spoken_messages Boolean        @default(true)\n\n  // Memory and personalisation\n  memory_enabled         Boolean @default(true)\n  use_past_conversations Boolean @default(true)\n\n  // Approvals\n  default_approval_level ApprovalLevel   @default(IMPORTANT_ACTIONS)\n  approval_timeout       ApprovalTimeout @default(KEEP_WAITING)\n  approval_channel       ApprovalChannel @default(IN_APP_PUSH)\n\n  // Cloud computer\n  auto_open_live_view Boolean @default(false)\n  notify_take_control Boolean @default(true)\n  keep_replays        Boolean @default(true)\n\n  // Connections\n  connection_problem_alerts Boolean @default(true)\n  secret_problem_alerts     Boolean @default(true)\n\n  // Tasks and automations\n  notify_task_finished   Boolean                      @default(true)\n  task_check_in          TaskCheckIn                  @default(HOUR_1)\n  automation_results_to  AutomationResultsDestination @default(BOT_CONVERSATION)\n  daily_briefing_enabled Boolean                      @default(false)\n  daily_briefing_time    String? // \"08:00\" in user's timezone\n\n  // Notifications\n  quiet_hours_enabled Boolean @default(false)\n  quiet_hours_start   String? // \"22:00\"\n  quiet_hours_end     String? // \"07:00\"\n  daily_email_digest  Boolean @default(false)\n  sounds_enabled      Boolean @default(true)\n\n  // Privacy and data\n  auto_delete_conversations ConversationRetention @default(NEVER)\n  /// §7.5 — off: deleted artifacts stay restorable forever; on: removed for good 30 days after deletion.\n  purge_deleted_artifacts   Boolean               @default(false)\n\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  user        User @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  default_bot Bot? @relation(\"UserDefaultBot\", fields: [default_bot_id], references: [id], onDelete: SetNull)\n\n  @@index([default_bot_id])\n  @@map(\"user_settings\")\n}\n\n/// §12 — per event: on/off and channels.\nmodel NotificationPreference {\n  id         String                @id @default(uuid())\n  user_id    String\n  event      NotificationEvent\n  enabled    Boolean               @default(true)\n  channels   NotificationChannel[] @default([IN_APP, PUSH])\n  updated_at DateTime              @updatedAt\n\n  user User @relation(fields: [user_id], references: [id], onDelete: Cascade)\n\n  @@unique([user_id, event])\n  @@map(\"notification_preferences\")\n}\n\n/// §13.2 Connections — \"Default account per service\".\nmodel UserServiceDefault {\n  id              String   @id @default(uuid())\n  user_id         String\n  organization_id String\n  service_key     String\n  connection_id   String\n  updated_at      DateTime @updatedAt\n\n  user         User         @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  connection   Connection   @relation(fields: [connection_id], references: [id], onDelete: Cascade)\n\n  @@unique([user_id, organization_id, service_key])\n  @@index([connection_id])\n  @@map(\"user_service_defaults\")\n}\n\n/// A user's permission for one tool of a connected service (e.g. NOTION_CREATE_PAGE). No row = AUTO_REVIEW.\nmodel UserToolPermission {\n  id              String         @id @default(uuid())\n  user_id         String\n  organization_id String\n  service_key     String\n  tool_slug       String\n  permission      ToolPermission\n  created_at      DateTime       @default(now())\n  updated_at      DateTime       @updatedAt\n\n  user         User         @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@unique([user_id, organization_id, service_key, tool_slug], map: \"user_tool_permissions_user_org_service_tool_key\")\n  @@index([organization_id, user_id, service_key], map: \"user_tool_permissions_org_user_service_idx\")\n  @@map(\"user_tool_permissions\")\n}\n\n// =====================================================================\n// ORGANISATIONS (§5, §13.4)\n// =====================================================================\n\nmodel Organization {\n  id                 String    @id @default(uuid())\n  name               String\n  slug               String    @unique\n  logo_file_id       String?   @unique\n  brand_color        String?\n  is_personal        Boolean   @default(false)\n  created_by_id      String?\n  stripe_customer_id String?   @unique\n  deleted_at         DateTime?\n  purge_after        DateTime?\n  created_at         DateTime  @default(now())\n  updated_at         DateTime  @updatedAt\n\n  logo              File?                      @relation(\"OrganizationLogo\", fields: [logo_file_id], references: [id], onDelete: SetNull)\n  created_by        User?                      @relation(\"OrganizationCreator\", fields: [created_by_id], references: [id], onDelete: SetNull)\n  settings          OrganizationSettings?\n  members           OrganizationMember[]\n  invitations       Invitation[]\n  allowed_models    OrganizationAllowedModel[]\n  allowed_templates OrganizationTemplate[]\n  starter_skills    OrganizationStarterSkill[]\n  bots              Bot[]\n  conversations     Conversation[]\n  folders           ConversationFolder[]\n  messages          Message[]\n  runs              Run[]\n  approvals         Approval[]\n  voice_sessions    VoiceSession[]\n  memories          Memory[]\n  knowledge_items   KnowledgeItem[]\n  skills            Skill[]\n  artifacts         Artifact[]\n  connections       Connection[]\n  credentials       Credential[]\n  tool_servers      ToolServer[]\n  files             File[]\n  cloud_computers   CloudComputer[]\n  automations       Automation[]\n  notifications     Notification[]\n  usage_charges     UsageCharge[]\n  usage_limits      UsageLimit[]\n  usage_alerts      UsageAlert[]\n  subscription      Subscription?\n  invoices          Invoice[]\n  activity_logs     ActivityLog[]\n  data_exports      DataExport[]\n  service_defaults  UserServiceDefault[]\n  tool_permissions  UserToolPermission[]\n  saved_widgets     SavedWidget[]\n\n  channel_links ChannelLink[]\n\n  @@index([created_by_id])\n  @@index([deleted_at])\n  @@map(\"organizations\")\n}\n\nmodel OrganizationSettings {\n  id              String @id @default(uuid())\n  organization_id String @unique\n\n  // General\n  default_language      AppLanguage @default(EN)\n  default_timezone      String      @default(\"UTC\")\n  default_working_hours Json?\n\n  // Members and invitations\n  invite_links_enabled Boolean          @default(true)\n  default_invite_role  OrganizationRole @default(MEMBER)\n  auto_join_domain     String?\n  invitation_expiry    InvitationExpiry @default(DAY_7)\n\n  // Bots\n  company_instructions String?\n  who_can_create_bots  WhoCan  @default(EVERYONE)\n  max_bots_per_member  Int?\n\n  // AI models\n  default_model_id      String?\n  model_policy          ModelPolicy @default(ALL_MODELS)\n  model_auto_fallback   Boolean     @default(true)\n  model_compare_enabled Boolean     @default(true)\n\n  // Connections and tools\n  service_policy               ServicePolicy          @default(ALL)\n  service_list                 String[]               @default([]) // approved or blocked keys depending on policy\n  members_private_tool_servers Boolean                @default(true)\n  members_api_key_connections  Boolean                @default(true)\n  builtin_web_search           Boolean                @default(true)\n  builtin_image_generation     Boolean                @default(true)\n  builtin_document_creation    Boolean                @default(true)\n  interactive_replies_mode     InteractiveRepliesMode @default(BLOCKS_AND_MINI_APPS)\n\n  // Device tools\n  device_tools_enabled       Boolean                  @default(true)\n  allowed_device_tools       DeviceToolKind[]         @default([LOCAL_FILES, SCREEN, LOCAL_TOOL_SERVERS, CLIPBOARD, OPEN, CONTROL_COMPUTER, CAMERA_SCANNER, CONTACTS, SEND_VIA_APPS, DEVICE_CALENDAR, LOCATION])\n  members_local_tool_servers Boolean                  @default(true)\n  automations_desktop_tools  Boolean                  @default(true)\n  biometric_approval_scopes  BiometricApprovalScope[] @default([])\n\n  // Cloud computers\n  cloud_computers_enabled      Boolean    @default(true)\n  cloud_computers_who          WhoCan     @default(EVERYONE)\n  computer_idle_pause          IdlePause  @default(MIN_15)\n  computer_max_session         MaxSession @default(HOUR_4)\n  computer_storage_limit_bytes BigInt?\n  members_take_control         Boolean    @default(true)\n  record_replays               Boolean    @default(true)\n  blocked_websites             String[]   @default([])\n\n  // Approvals and safety\n  min_approval_level       MinApprovalLevel      @default(NONE)\n  enforced_approvals       ActionType[]          @default([EXTERNAL_EMAIL, PURCHASE_PAYMENT])\n  bots_consulting_enabled  Boolean               @default(true)\n  approval_timeout_minutes Int? // null = keep waiting\n  approval_timeout_action  ApprovalTimeoutAction @default(CANCEL) // enforced / tap-only actions are always cancelled\n\n  // Skills\n  who_can_create_skills  WhoCan  @default(EVERYONE)\n  starter_skills_enabled Boolean @default(true)\n  skill_import_enabled   Boolean @default(true)\n\n  // Artifacts\n  artifacts_enabled            Boolean               @default(true)\n  public_link_policy           PublicLinkPolicy      @default(EVERYONE)\n  public_link_require_password Boolean               @default(false)\n  public_link_max_lifetime     PublicLinkLifetime    @default(NO_LIMIT)\n  public_artifact_ai_enabled   Boolean               @default(true)\n  public_artifact_uploads      Boolean               @default(true)\n  artifact_embedding_enabled   Boolean               @default(true)\n  artifact_design_default      ArtifactDesignDefault @default(ORGANIZATION_BRAND)\n\n  // Voice mode\n  voice_mode_enabled      Boolean            @default(true)\n  /// §7.6 — camera and screen sharing in voice mode.\n  voice_visual_input      Boolean            @default(true)\n  voice_mode_who          WhoCan             @default(EVERYONE)\n  voice_max_session       VoiceSessionLength @default(MIN_30)\n  voice_approvals_enabled Boolean            @default(true)\n  voice_keep_transcripts  Boolean            @default(true)\n  voice_model             String? // OpenAI Realtime model id (voice-models.ts); null = platform default\n\n  // Automations\n  automations_enabled        Boolean           @default(true)\n  max_automations_per_member Int?\n  automations_cloud_computer Boolean           @default(true)\n  automation_pre_approvals   Boolean           @default(true)\n  max_schedule_frequency     ScheduleFrequency @default(EVERY_HOUR)\n\n  // Usage and limits\n  usage_alert_thresholds Int[]              @default([80, 100])\n  limit_reached_action   LimitReachedAction @default(PAUSE_AND_NOTIFY)\n\n  // Data and privacy\n  conversation_retention  OrgConversationRetention @default(FOREVER)\n  computer_retention      ComputerRetention        @default(DAYS_90)\n  max_file_size           MaxFileSize              @default(MB_100)\n  members_may_export      Boolean                  @default(true)\n  temporary_chats_allowed Boolean                  @default(true)\n\n  // Security\n  require_two_factor      Boolean           @default(false)\n  allowed_sign_in_methods AuthProvider[]    @default([EMAIL, GOOGLE, MICROSOFT, APPLE])\n  session_inactivity      SessionInactivity @default(DAYS_30)\n\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  organization  Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  default_model AiModel?     @relation(fields: [default_model_id], references: [id], onDelete: SetNull)\n\n  @@index([default_model_id])\n  @@map(\"organization_settings\")\n}\n\nmodel OrganizationMember {\n  id                String           @id @default(uuid())\n  organization_id   String\n  user_id           String\n  role              OrganizationRole @default(MEMBER)\n  /// This member's colour theme inside this organisation (each org can look different per user).\n  color_theme       ColorTheme       @default(NEUTRAL)\n  /// §16 Meeting assistant set-up: { bot_id, calendar_connection_id, email_connection_id, briefs_automation_id, follow_ups_automation_id }.\n  meeting_assistant Json?\n  joined_at         DateTime         @default(now())\n  updated_at        DateTime         @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  user         User         @relation(fields: [user_id], references: [id], onDelete: Cascade)\n\n  @@unique([organization_id, user_id])\n  @@index([user_id])\n  @@map(\"organization_members\")\n}\n\nmodel Invitation {\n  id              String           @id @default(uuid())\n  organization_id String\n  email           String?\n  token_hash      String           @unique\n  is_link         Boolean          @default(false)\n  role            OrganizationRole @default(MEMBER)\n  status          InvitationStatus @default(PENDING)\n  invited_by_id   String?\n  accepted_by_id  String?\n  expires_at      DateTime\n  accepted_at     DateTime?\n  created_at      DateTime         @default(now())\n  updated_at      DateTime         @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  invited_by   User?        @relation(\"InvitationInviter\", fields: [invited_by_id], references: [id], onDelete: SetNull)\n  accepted_by  User?        @relation(\"InvitationAcceptor\", fields: [accepted_by_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, status])\n  @@index([email])\n  @@index([invited_by_id])\n  @@index([accepted_by_id])\n  @@map(\"invitations\")\n}\n\n// =====================================================================\n// AI MODELS (§6.4)\n// =====================================================================\n\n/// Catalogue of models available through OpenRouter, refreshed hourly (§14.4 caches), persisted for references.\nmodel AiModel {\n  id                 String        @id @default(uuid())\n  openrouter_id      String        @unique // e.g. \"anthropic/claude-sonnet-4\"\n  name               String\n  provider           String // Anthropic, OpenAI, Google, xAI, Meta, Mistral…\n  labels             String[]      @default([]) // \"fast\", \"smart\", \"writing\", \"coding\", \"vision\"\n  cost_tier          ModelCostTier @default(MEDIUM)\n  input_price_per_m  Decimal?      @db.Decimal(12, 6)\n  output_price_per_m Decimal?      @db.Decimal(12, 6)\n  context_length     Int?\n  supports_vision    Boolean       @default(false)\n  supports_tools     Boolean       @default(true)\n  is_recommended     Boolean       @default(false)\n  is_available       Boolean       @default(true)\n  fallback_model_id  String?\n  created_at         DateTime      @default(now())\n  updated_at         DateTime      @updatedAt\n\n  fallback_model AiModel?                   @relation(\"ModelFallback\", fields: [fallback_model_id], references: [id], onDelete: SetNull)\n  fallbacks_for  AiModel[]                  @relation(\"ModelFallback\")\n  bots           Bot[]\n  bot_templates  BotTemplate[]\n  org_defaults   OrganizationSettings[]\n  org_allowed    OrganizationAllowedModel[]\n  runs           Run[]\n  usage_charges  UsageCharge[]\n\n  @@index([fallback_model_id])\n  @@index([is_available, is_recommended])\n  @@map(\"ai_models\")\n}\n\nmodel OrganizationAllowedModel {\n  organization_id String\n  model_id        String\n  created_at      DateTime @default(now())\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  model        AiModel      @relation(fields: [model_id], references: [id], onDelete: Cascade)\n\n  @@id([organization_id, model_id])\n  @@index([model_id])\n  @@map(\"organization_allowed_models\")\n}\n\n// =====================================================================\n// BOTS (§6, §13.3)\n// =====================================================================\n\n/// §6.1 — six launch templates (Personal Assistant, Sales, Marketing, Support, Researcher, Executive Assistant).\nmodel BotTemplate {\n  id                    String        @id @default(uuid())\n  key                   String        @unique\n  name                  String\n  /// Deprecated, no longer read or written. Drop once every deployment runs the avatar_seed code.\n  emoji                 String        @default(\"\")\n  /// Seed for the generated flat-portrait avatar (same generator as bots).\n  avatar_seed           String        @default(dbgenerated(\"substr(md5(random()::text), 1, 12)\"))\n  color                 String\n  description           String\n  instructions          String\n  welcome_message       String?\n  conversation_starters String[]      @default([])\n  suggested_services    String[]      @default([])\n  model_id              String?\n  voice                 String?\n  approval_level        ApprovalLevel @default(IMPORTANT_ACTIONS)\n  cloud_computer        Boolean       @default(false)\n  sort_order            Int           @default(0)\n  is_active             Boolean       @default(true)\n  created_at            DateTime      @default(now())\n  updated_at            DateTime      @updatedAt\n\n  model          AiModel?               @relation(fields: [model_id], references: [id], onDelete: SetNull)\n  starter_skills BotTemplateSkill[]\n  bots           Bot[]\n  organizations  OrganizationTemplate[]\n\n  @@index([model_id])\n  @@map(\"bot_templates\")\n}\n\nmodel BotTemplateSkill {\n  template_id String\n  skill_id    String\n\n  template BotTemplate @relation(fields: [template_id], references: [id], onDelete: Cascade)\n  skill    Skill       @relation(fields: [skill_id], references: [id], onDelete: Cascade)\n\n  @@id([template_id, skill_id])\n  @@index([skill_id])\n  @@map(\"bot_template_skills\")\n}\n\n/// §13.4 Bots — \"Available templates\": which templates members of an org see.\nmodel OrganizationTemplate {\n  organization_id String\n  template_id     String\n  enabled         Boolean @default(true)\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  template     BotTemplate  @relation(fields: [template_id], references: [id], onDelete: Cascade)\n\n  @@id([organization_id, template_id])\n  @@index([template_id])\n  @@map(\"organization_templates\")\n}\n\nmodel Bot {\n  id                 String  @id @default(uuid())\n  organization_id    String\n  created_by_id      String?\n  template_id        String?\n  duplicated_from_id String?\n  /// The bot created at sign-up. It configures itself through chat and cannot be deleted.\n  is_starter         Boolean @default(false)\n\n  // Identity\n  name                  String\n  /// Deprecated, no longer read or written. Drop once every deployment runs the avatar_seed code.\n  emoji                 String   @default(\"🤖\")\n  /// Seed for the generated flat-portrait avatar. Shuffling picks a new one; the colour stays the bot colour.\n  avatar_seed           String   @default(dbgenerated(\"substr(md5(random()::text), 1, 12)\"))\n  color                 String   @default(\"#6366F1\")\n  description           String?\n  image_file_id         String?  @unique\n  welcome_message       String?\n  conversation_starters String[] @default([]) // max 4\n\n  // Behaviour\n  instructions         String\n  model_id             String? // null = organisation default / Recommended\n  creativity           Creativity             @default(BALANCED)\n  style_override       Boolean                @default(false)\n  reply_length         ReplyLength?\n  reply_tone           ReplyTone?\n  reply_formatting     ReplyFormatting?\n  emoji_usage          EmojiUsage?\n  lock_style           Boolean                @default(false)\n  reply_language       AppLanguage? // null = same as the user's message\n  clarifying_questions BotClarifyingQuestions @default(USER_PREFERENCE)\n  group_response       BotGroupResponse       @default(WHEN_RELEVANT_OR_MENTIONED)\n\n  // Abilities\n  web_search_enabled        Boolean                @default(true)\n  image_generation_enabled  Boolean                @default(true)\n  document_creation_enabled Boolean                @default(true)\n  interactive_replies_mode  InteractiveRepliesMode @default(BLOCKS_AND_MINI_APPS)\n  artifacts_enabled         Boolean                @default(true)\n  cloud_computer_enabled    Boolean                @default(false)\n  use_skills_automatically  Boolean                @default(true)\n  org_knowledge_enabled     Boolean                @default(true)\n\n  // Voice\n  voice_mode_enabled Boolean          @default(true)\n  voice              String? // null = default voice\n  spoken_reply_style SpokenReplyStyle @default(SHORT_CONVERSATIONAL)\n\n  // Memory\n  memory_enabled Boolean     @default(true)\n  memory_scope   MemoryScope @default(PER_USER)\n\n  // Working with other bots\n  can_ask_other_bots Boolean @default(true)\n  can_be_asked       Boolean @default(true)\n  is_sensitive       Boolean @default(false)\n\n  // Approvals\n  approval_level ApprovalLevel @default(IMPORTANT_ACTIONS)\n\n  // Limits\n  max_task_duration   MaxTaskDuration @default(HOUR_1)\n  monthly_usage_limit Decimal?        @db.Decimal(12, 4)\n\n  // Sharing\n  visibility  BotVisibility @default(PRIVATE)\n  edit_policy BotEditPolicy @default(CREATOR_ONLY)\n\n  is_archived Boolean   @default(false)\n  deleted_at  DateTime?\n  created_at  DateTime  @default(now())\n  updated_at  DateTime  @updatedAt\n\n  organization    Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  created_by      User?        @relation(\"BotCreator\", fields: [created_by_id], references: [id], onDelete: SetNull)\n  template        BotTemplate? @relation(fields: [template_id], references: [id], onDelete: SetNull)\n  duplicated_from Bot?         @relation(\"BotDuplicate\", fields: [duplicated_from_id], references: [id], onDelete: SetNull)\n  duplicates      Bot[]        @relation(\"BotDuplicate\")\n  model           AiModel?     @relation(fields: [model_id], references: [id], onDelete: SetNull)\n  image           File?        @relation(\"BotImage\", fields: [image_file_id], references: [id], onDelete: SetNull)\n\n  approval_rules            BotApprovalRule[]\n  bot_connections           BotConnection[]\n  bot_tool_servers          BotToolServer[]\n  bot_credentials           BotCredential[]\n  bot_skills                BotSkill[]\n  knowledge_items           KnowledgeItem[]\n  memories                  Memory[]\n  cloud_computer            CloudComputer?\n  participations            ConversationParticipant[]\n  lead_conversations        Conversation[]             @relation(\"ConversationLeadBot\")\n  messages                  Message[]                  @relation(\"MessageBotAuthor\")\n  runs                      Run[]                      @relation(\"RunBot\")\n  consultations             Run[]                      @relation(\"RunRequestedByBot\")\n  approvals                 Approval[]\n  voice_sessions            VoiceSession[]\n  automations               Automation[]\n  usage_charges             UsageCharge[]\n  usage_limits              UsageLimit[]\n  activity_logs             ActivityLog[]\n  default_for_users         UserSettings[]             @relation(\"UserDefaultBot\")\n  connection_restrictions   ConnectionBotRestriction[]\n  credential_last_used      Credential[]               @relation(\"CredentialLastUsedBot\")\n  artifact_comment_mentions ArtifactComment[]          @relation(\"ArtifactCommentBotMention\")\n\n  channel_links ChannelLink[]\n\n  @@index([organization_id, visibility])\n  @@index([created_by_id])\n  @@index([template_id])\n  @@index([model_id])\n  @@index([duplicated_from_id])\n  @@index([deleted_at])\n  @@map(\"bots\")\n}\n\n/// §13.3 Approvals — per action type override.\nmodel BotApprovalRule {\n  id          String           @id @default(uuid())\n  bot_id      String\n  action_type ActionType\n  override    ApprovalOverride\n  updated_at  DateTime         @updatedAt\n\n  bot Bot @relation(fields: [bot_id], references: [id], onDelete: Cascade)\n\n  @@unique([bot_id, action_type])\n  @@map(\"bot_approval_rules\")\n}\n\n/// Which connected accounts a bot may use, and the default per service (§13.3 Abilities).\nmodel BotConnection {\n  id                     String   @id @default(uuid())\n  bot_id                 String\n  connection_id          String\n  is_default_for_service Boolean  @default(false)\n  created_at             DateTime @default(now())\n\n  bot        Bot        @relation(fields: [bot_id], references: [id], onDelete: Cascade)\n  connection Connection @relation(fields: [connection_id], references: [id], onDelete: Cascade)\n\n  @@unique([bot_id, connection_id])\n  @@index([connection_id])\n  @@map(\"bot_connections\")\n}\n\nmodel BotToolServer {\n  bot_id         String\n  tool_server_id String\n  created_at     DateTime @default(now())\n\n  bot         Bot        @relation(fields: [bot_id], references: [id], onDelete: Cascade)\n  tool_server ToolServer @relation(fields: [tool_server_id], references: [id], onDelete: Cascade)\n\n  @@id([bot_id, tool_server_id])\n  @@index([tool_server_id])\n  @@map(\"bot_tool_servers\")\n}\n\n/// §8.9 \"Choose bots\" — which bots may use a secret.\nmodel BotCredential {\n  bot_id        String\n  credential_id String\n  created_at    DateTime @default(now())\n\n  bot        Bot        @relation(fields: [bot_id], references: [id], onDelete: Cascade)\n  credential Credential @relation(fields: [credential_id], references: [id], onDelete: Cascade)\n\n  @@id([bot_id, credential_id])\n  @@index([credential_id])\n  @@map(\"bot_credentials\")\n}\n\nmodel BotSkill {\n  bot_id      String\n  skill_id    String\n  assigned_at DateTime @default(now())\n\n  bot   Bot   @relation(fields: [bot_id], references: [id], onDelete: Cascade)\n  skill Skill @relation(fields: [skill_id], references: [id], onDelete: Cascade)\n\n  @@id([bot_id, skill_id])\n  @@index([skill_id])\n  @@map(\"bot_skills\")\n}\n\n/// §6.2 Knowledge and §13.4 organisation knowledge library. Files, links or text.\nmodel KnowledgeItem {\n  id              String          @id @default(uuid())\n  organization_id String\n  scope           KnowledgeScope\n  bot_id          String?\n  kind            KnowledgeKind\n  title           String\n  file_id         String?         @unique\n  url             String?\n  content         String?\n  status          KnowledgeStatus @default(PROCESSING)\n  /// Why indexing failed, in words people can act on (status FAILED).\n  status_error    String?\n  added_by_id     String?\n  indexed_at      DateTime?\n  deleted_at      DateTime?\n  created_at      DateTime        @default(now())\n  updated_at      DateTime        @updatedAt\n\n  organization Organization     @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  bot          Bot?             @relation(fields: [bot_id], references: [id], onDelete: Cascade)\n  file         File?            @relation(fields: [file_id], references: [id], onDelete: SetNull)\n  added_by     User?            @relation(fields: [added_by_id], references: [id], onDelete: SetNull)\n  links        KnowledgeLink[]\n  chunks       KnowledgeChunk[]\n\n  @@index([organization_id, scope])\n  @@index([bot_id])\n  @@index([added_by_id])\n  @@map(\"knowledge_items\")\n}\n\n/// A passage of a knowledge item with its embedding, for vector search (search_knowledge).\nmodel KnowledgeChunk {\n  id                String   @id @default(uuid())\n  knowledge_item_id String\n  position          Int\n  content           String\n  /// Float32 little-endian vector (EMBEDDING_DIMS values) of \"title + content\".\n  embedding         Bytes\n  created_at        DateTime @default(now())\n\n  knowledge_item KnowledgeItem @relation(fields: [knowledge_item_id], references: [id], onDelete: Cascade)\n\n  @@unique([knowledge_item_id, position])\n  @@map(\"knowledge_chunks\")\n}\n\n/// Links in a knowledge item that were crawled (one row per fetched page).\nmodel KnowledgeLink {\n  id                String    @id @default(uuid())\n  knowledge_item_id String\n  url               String\n  title             String?\n  fetched_at        DateTime?\n  fetched_by_id     String?\n  created_at        DateTime  @default(now())\n\n  knowledge_item KnowledgeItem @relation(fields: [knowledge_item_id], references: [id], onDelete: Cascade)\n  fetched_by     User?         @relation(fields: [fetched_by_id], references: [id], onDelete: SetNull)\n\n  @@index([knowledge_item_id])\n  @@index([fetched_by_id])\n  @@map(\"knowledge_links\")\n}\n\n/// §6.3 — bot memory (per user or shared) and organisation-level memory.\nmodel Memory {\n  id                     String     @id @default(uuid())\n  organization_id        String\n  kind                   MemoryKind\n  bot_id                 String?\n  user_id                String?\n  content                String\n  source_conversation_id String?\n  source_message_id      String?\n  last_recalled_at       DateTime?\n  created_at             DateTime   @default(now())\n  updated_at             DateTime   @updatedAt\n\n  organization        Organization  @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  bot                 Bot?          @relation(fields: [bot_id], references: [id], onDelete: Cascade)\n  user                User?         @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  source_conversation Conversation? @relation(fields: [source_conversation_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, kind])\n  @@index([bot_id, user_id])\n  @@index([user_id])\n  @@index([source_conversation_id])\n  @@map(\"memories\")\n}\n\n// =====================================================================\n// CONVERSATIONS AND MESSAGES (§7)\n// =====================================================================\n\nmodel ConversationFolder {\n  id              String   @id @default(uuid())\n  organization_id String\n  user_id         String\n  name            String\n  sort_order      Int      @default(0)\n  created_at      DateTime @default(now())\n  updated_at      DateTime @updatedAt\n\n  organization Organization              @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  user         User                      @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  participants ConversationParticipant[]\n\n  @@index([user_id, organization_id])\n  @@index([organization_id])\n  @@map(\"conversation_folders\")\n}\n\nmodel Conversation {\n  id              String           @id @default(uuid())\n  organization_id String\n  type            ConversationType\n  name            String?\n  /// Deprecated, no longer read or written. Drop with Bot.emoji.\n  emoji           String?\n  color           String?\n  /// Groups only: seed for the group's generated portrait avatar (same generator as bots).\n  avatar_seed     String?\n  lead_bot_id     String?\n  created_by_id   String?\n  is_temporary    Boolean          @default(false)\n  last_message_at DateTime?\n  message_count   Int              @default(0)\n  deleted_at      DateTime?\n  created_at      DateTime         @default(now())\n  updated_at      DateTime         @updatedAt\n\n  organization        Organization              @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  lead_bot            Bot?                      @relation(\"ConversationLeadBot\", fields: [lead_bot_id], references: [id], onDelete: SetNull)\n  created_by          User?                     @relation(\"ConversationCreator\", fields: [created_by_id], references: [id], onDelete: SetNull)\n  participants        ConversationParticipant[]\n  messages            Message[]\n  runs                Run[]\n  approvals           Approval[]\n  voice_sessions      VoiceSession[]\n  memories            Memory[]\n  artifacts           Artifact[]\n  files               File[]\n  automations_results Automation[]              @relation(\"AutomationResultConversation\")\n  automations_source  Automation[]              @relation(\"AutomationSourceConversation\")\n  saved_widgets       SavedWidget[]\n\n  channel_links ChannelLink[]\n  share         ConversationShare?\n\n  @@index([organization_id, type])\n  @@index([lead_bot_id])\n  @@index([created_by_id])\n  @@index([last_message_at])\n  @@index([deleted_at])\n  @@map(\"conversations\")\n}\n\n/// A user or a bot in a conversation. Exactly one of user_id / bot_id is set.\n/// A public, read-only link to a conversation. One per conversation; stopping the share deletes the row, which kills the link.\nmodel ConversationShare {\n  id              String                @id @default(uuid())\n  conversation_id String                @unique\n  created_by_id   String?\n  /// Unguessable URL token (the link is the credential).\n  token           String                @unique\n  mode            ConversationShareMode @default(SNAPSHOT)\n  /// SNAPSHOT mode: only messages created at or before this moment are visible.\n  cutoff_at       DateTime\n  created_at      DateTime              @default(now())\n  updated_at      DateTime              @updatedAt\n\n  conversation Conversation @relation(fields: [conversation_id], references: [id], onDelete: Cascade)\n  created_by   User?        @relation(fields: [created_by_id], references: [id], onDelete: SetNull)\n\n  @@map(\"conversation_shares\")\n}\n\nmodel ConversationParticipant {\n  id              String    @id @default(uuid())\n  conversation_id String\n  user_id         String?\n  bot_id          String?\n  folder_id       String?\n  is_favourite    Boolean   @default(false)\n  is_archived     Boolean   @default(false)\n  is_muted        Boolean   @default(false)\n  last_read_at    DateTime?\n  unread_count    Int       @default(0)\n  joined_at       DateTime  @default(now())\n  left_at         DateTime?\n\n  conversation Conversation        @relation(fields: [conversation_id], references: [id], onDelete: Cascade)\n  user         User?               @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  bot          Bot?                @relation(fields: [bot_id], references: [id], onDelete: Cascade)\n  folder       ConversationFolder? @relation(fields: [folder_id], references: [id], onDelete: SetNull)\n\n  @@unique([conversation_id, user_id])\n  @@unique([conversation_id, bot_id])\n  @@index([user_id, is_archived])\n  @@index([bot_id])\n  @@index([folder_id])\n  @@map(\"conversation_participants\")\n}\n\nmodel Message {\n  id                     String            @id @default(uuid())\n  organization_id        String\n  conversation_id        String\n  author_type            MessageAuthorType\n  author_user_id         String?\n  author_bot_id          String?\n  source                 MessageSource     @default(TEXT)\n  status                 MessageStatus     @default(COMPLETED)\n  /// Plain-text content (also the fallback for interactive replies). Secrets are masked before storage (§8.8).\n  content                String?\n  /// Vercel AI SDK message parts: text, tool-invocation, interactive (json-render spec / mini-app), approval, secret-input, file…\n  parts                  Json?\n  /// Messages that came from email, Slack or WhatsApp: where to send the reply (thread, subject, sender).\n  channel_meta           Json?\n  run_id                 String?\n  parent_message_id      String? // thread reply\n  reply_to_message_id    String? // quoted message (\"reply to\" a specific message)\n  branch_from_message_id String? // \"try a different approach\"\n  branch_index           Int               @default(0)\n  model_id               String? // which model produced it (for compare / retry)\n  is_pinned              Boolean           @default(false)\n  pinned_by_id           String?\n  pinned_at              DateTime?\n  edited_at              DateTime?\n  secret_masked          Boolean           @default(false)\n  deleted_at             DateTime?\n  created_at             DateTime          @default(now())\n  updated_at             DateTime          @updatedAt\n\n  organization          Organization          @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  conversation          Conversation          @relation(fields: [conversation_id], references: [id], onDelete: Cascade)\n  author_user           User?                 @relation(\"MessageUserAuthor\", fields: [author_user_id], references: [id], onDelete: SetNull)\n  author_bot            Bot?                  @relation(\"MessageBotAuthor\", fields: [author_bot_id], references: [id], onDelete: SetNull)\n  run                   Run?                  @relation(\"RunMessages\", fields: [run_id], references: [id], onDelete: SetNull)\n  parent                Message?              @relation(\"MessageThread\", fields: [parent_message_id], references: [id], onDelete: SetNull)\n  replies               Message[]             @relation(\"MessageThread\")\n  reply_to              Message?              @relation(\"MessageReplyTo\", fields: [reply_to_message_id], references: [id], onDelete: SetNull)\n  quoted_by             Message[]             @relation(\"MessageReplyTo\")\n  branch_from           Message?              @relation(\"MessageBranch\", fields: [branch_from_message_id], references: [id], onDelete: SetNull)\n  branches              Message[]             @relation(\"MessageBranch\")\n  pinned_by             User?                 @relation(\"MessagePinnedBy\", fields: [pinned_by_id], references: [id], onDelete: SetNull)\n  files                 MessageFile[]\n  reactions             MessageReaction[]\n  mentions              MessageMention[]\n  approvals             Approval[]\n  interactive_responses InteractiveResponse[]\n  saved_widgets         SavedWidget[]\n  artifacts             Artifact[]\n  triggered_runs        Run[]                 @relation(\"RunTriggerMessage\")\n\n  @@index([conversation_id, created_at])\n  @@index([organization_id])\n  @@index([author_user_id])\n  @@index([author_bot_id])\n  @@index([run_id])\n  @@index([parent_message_id])\n  @@index([reply_to_message_id])\n  @@index([branch_from_message_id])\n  @@index([pinned_by_id])\n  @@index([conversation_id, is_pinned])\n  @@map(\"messages\")\n}\n\nmodel MessageFile {\n  message_id String\n  file_id    String\n  sort_order Int    @default(0)\n\n  message Message @relation(fields: [message_id], references: [id], onDelete: Cascade)\n  file    File    @relation(fields: [file_id], references: [id], onDelete: Cascade)\n\n  @@id([message_id, file_id])\n  @@index([file_id])\n  @@map(\"message_files\")\n}\n\nmodel MessageReaction {\n  id         String   @id @default(uuid())\n  message_id String\n  user_id    String\n  emoji      String\n  created_at DateTime @default(now())\n\n  message Message @relation(fields: [message_id], references: [id], onDelete: Cascade)\n  user    User    @relation(fields: [user_id], references: [id], onDelete: Cascade)\n\n  @@unique([message_id, user_id, emoji])\n  @@index([user_id])\n  @@map(\"message_reactions\")\n}\n\n/// @mentions of users/bots and /mentions of skills inside a message.\nmodel MessageMention {\n  id         String  @id @default(uuid())\n  message_id String\n  user_id    String?\n  bot_id     String?\n  skill_id   String?\n\n  message Message @relation(fields: [message_id], references: [id], onDelete: Cascade)\n  skill   Skill?  @relation(fields: [skill_id], references: [id], onDelete: SetNull)\n\n  @@index([message_id])\n  @@index([user_id])\n  @@index([bot_id])\n  @@index([skill_id])\n  @@map(\"message_mentions\")\n}\n\n/// §7.4 — a user's input into an interactive reply (form submission, vote, click). Combined in groups.\nmodel InteractiveResponse {\n  id           String   @id @default(uuid())\n  message_id   String\n  component_id String\n  user_id      String\n  payload      Json\n  created_at   DateTime @default(now())\n\n  message Message @relation(fields: [message_id], references: [id], onDelete: Cascade)\n\n  @@index([message_id, component_id])\n  @@index([user_id])\n  @@map(\"interactive_responses\")\n}\n\n/// §7.4 — an interactive reply saved as a widget, refreshed each time it's opened.\nmodel SavedWidget {\n  id                String   @id @default(uuid())\n  organization_id   String\n  user_id           String\n  conversation_id   String?\n  source_message_id String?\n  title             String\n  spec              Json // json-render spec or mini-app source + data query\n  refresh_prompt    String?\n  created_at        DateTime @default(now())\n  updated_at        DateTime @updatedAt\n\n  organization   Organization  @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  user           User          @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  conversation   Conversation? @relation(fields: [conversation_id], references: [id], onDelete: SetNull)\n  source_message Message?      @relation(fields: [source_message_id], references: [id], onDelete: SetNull)\n\n  @@index([user_id, organization_id])\n  @@index([organization_id])\n  @@index([conversation_id])\n  @@index([source_message_id])\n  @@map(\"saved_widgets\")\n}\n\n// =====================================================================\n// RUNS, STEPS, APPROVALS, VOICE (§7.3, §10.1, §11, §7.6, §14.4)\n// =====================================================================\n\n/// A bot run: chat reply, long task, automation run or bot-to-bot request. Job ID in `agent-runs` = run ID.\nmodel Run {\n  id                  String    @id @default(uuid())\n  organization_id     String\n  conversation_id     String?\n  bot_id              String\n  user_id             String? // on whose behalf\n  type                RunType\n  status              RunStatus @default(QUEUED)\n  priority            Int       @default(3)\n  title               String?\n  trigger_message_id  String?\n  parent_run_id       String? // bot-to-bot: the run that asked\n  requested_by_bot_id String?\n  automation_run_id   String?   @unique\n  voice_session_id    String?\n  model_id            String?\n  fallback_used       Boolean   @default(false)\n  skill_id            String?\n  uses_computer       Boolean   @default(false)\n  /// Saved loop state while waiting (§14.4 \"Waiting doesn't hold a worker\").\n  state               Json?\n  error               String?\n  input_tokens        Int       @default(0)\n  output_tokens       Int       @default(0)\n  cost                Decimal   @default(0) @db.Decimal(12, 6)\n  queued_at           DateTime  @default(now())\n  started_at          DateTime?\n  finished_at         DateTime?\n  deadline_at         DateTime?\n  last_check_in_at    DateTime?\n  created_at          DateTime  @default(now())\n  updated_at          DateTime  @updatedAt\n\n  organization      Organization       @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  conversation      Conversation?      @relation(fields: [conversation_id], references: [id], onDelete: Cascade)\n  bot               Bot                @relation(\"RunBot\", fields: [bot_id], references: [id], onDelete: Cascade)\n  user              User?              @relation(\"RunUser\", fields: [user_id], references: [id], onDelete: SetNull)\n  trigger_message   Message?           @relation(\"RunTriggerMessage\", fields: [trigger_message_id], references: [id], onDelete: SetNull)\n  parent_run        Run?               @relation(\"RunParent\", fields: [parent_run_id], references: [id], onDelete: SetNull)\n  child_runs        Run[]              @relation(\"RunParent\")\n  requested_by_bot  Bot?               @relation(\"RunRequestedByBot\", fields: [requested_by_bot_id], references: [id], onDelete: SetNull)\n  automation_run    AutomationRun?     @relation(fields: [automation_run_id], references: [id], onDelete: SetNull)\n  voice_session     VoiceSession?      @relation(fields: [voice_session_id], references: [id], onDelete: SetNull)\n  model             AiModel?           @relation(fields: [model_id], references: [id], onDelete: SetNull)\n  skill             Skill?             @relation(fields: [skill_id], references: [id], onDelete: SetNull)\n  messages          Message[]          @relation(\"RunMessages\")\n  steps             RunStep[]\n  approvals         Approval[]\n  computer_sessions ComputerSession[]\n  transfers         ComputerTransfer[]\n  usage_charges     UsageCharge[]\n  activity_logs     ActivityLog[]\n  artifact_versions ArtifactVersion[]\n  files             File[]\n\n  @@index([organization_id, status])\n  @@index([conversation_id, bot_id, status])\n  @@index([bot_id])\n  @@index([user_id, status])\n  @@index([trigger_message_id])\n  @@index([parent_run_id])\n  @@index([requested_by_bot_id])\n  @@index([voice_session_id])\n  @@index([model_id])\n  @@index([skill_id])\n  @@index([type, status])\n  @@map(\"runs\")\n}\n\n/// §7.3 — the live activity feed. Also published to the conversation's Redis Stream.\nmodel RunStep {\n  id               String        @id @default(uuid())\n  run_id           String\n  sequence         Int\n  type             RunStepType\n  status           RunStepStatus @default(RUNNING)\n  title            String // \"Searching your Gmail (sales@)…\"\n  tool_name        String?\n  runs_on          ToolRunsOn    @default(SERVER)\n  connection_id    String?\n  device_id        String?\n  skill_id         String?\n  consulted_bot_id String?\n  /// Redacted input/output (§8.7 redaction applied before storage).\n  input            Json?\n  output           Json?\n  error            String?\n  started_at       DateTime      @default(now())\n  finished_at      DateTime?\n  duration_ms      Int?\n  /// §16 Undo: how to reverse this step in the connected service ({ tool, args, label, connection_id }); never shown to the model.\n  undo             Json?\n  undo_until       DateTime?\n  undone_at        DateTime?\n  undone_by_id     String?\n\n  run        Run         @relation(fields: [run_id], references: [id], onDelete: Cascade)\n  connection Connection? @relation(fields: [connection_id], references: [id], onDelete: SetNull)\n  device     Device?     @relation(fields: [device_id], references: [id], onDelete: SetNull)\n  skill      Skill?      @relation(fields: [skill_id], references: [id], onDelete: SetNull)\n\n  @@unique([run_id, sequence])\n  @@index([connection_id])\n  @@index([device_id])\n  @@index([skill_id])\n  @@index([consulted_bot_id])\n  @@map(\"run_steps\")\n}\n\n/// §11 — an approval request. Delayed `approvals.timeout` job ID = approval:<id>.\nmodel Approval {\n  id                 String         @id @default(uuid())\n  organization_id    String\n  run_id             String\n  conversation_id    String?\n  message_id         String?\n  bot_id             String\n  requested_from_id  String? // the user who must answer\n  action_type        ActionType\n  title              String\n  /// The exact preview shown on the card (e.g. the email to be sent). Secrets never included.\n  preview            Json\n  /// Tool call held open until resolved.\n  tool_call_id       String?\n  status             ApprovalStatus @default(PENDING)\n  is_urgent          Boolean        @default(false)\n  requires_tap       Boolean        @default(false) // payments / passwords: never voice alone\n  requires_biometric Boolean        @default(false)\n  resolved_via_voice Boolean        @default(false)\n  edited_payload     Json?\n  resolved_by_id     String?\n  resolved_at        DateTime?\n  timeout_at         DateTime?\n  created_at         DateTime       @default(now())\n  updated_at         DateTime       @updatedAt\n\n  organization Organization  @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  run          Run           @relation(fields: [run_id], references: [id], onDelete: Cascade)\n  conversation Conversation? @relation(fields: [conversation_id], references: [id], onDelete: Cascade)\n  message      Message?      @relation(fields: [message_id], references: [id], onDelete: SetNull)\n  bot          Bot           @relation(fields: [bot_id], references: [id], onDelete: Cascade)\n  resolved_by  User?         @relation(\"ApprovalResolver\", fields: [resolved_by_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, status])\n  @@index([run_id])\n  @@index([conversation_id])\n  @@index([message_id])\n  @@index([bot_id])\n  @@index([requested_from_id, status])\n  @@index([resolved_by_id])\n  @@index([timeout_at])\n  @@map(\"approvals\")\n}\n\n/// §7.6 — one real-time voice session (OpenAI Realtime). Audio is never stored.\nmodel VoiceSession {\n  id                  String                 @id @default(uuid())\n  organization_id     String\n  conversation_id     String\n  user_id             String\n  bot_id              String\n  provider_session_id String?\n  input_mode          VoiceInputMode         @default(HANDS_FREE)\n  voice               String?\n  started_at          DateTime               @default(now())\n  ended_at            DateTime?\n  end_reason          VoiceSessionEndReason?\n  audio_seconds       Int                    @default(0)\n  input_tokens        Int                    @default(0)\n  output_tokens       Int                    @default(0)\n  cost                Decimal                @default(0) @db.Decimal(12, 6)\n  created_at          DateTime               @default(now())\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  conversation Conversation @relation(fields: [conversation_id], references: [id], onDelete: Cascade)\n  user         User         @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  bot          Bot          @relation(fields: [bot_id], references: [id], onDelete: Cascade)\n  runs         Run[]\n\n  @@index([organization_id, started_at])\n  @@index([conversation_id])\n  @@index([user_id])\n  @@index([bot_id])\n  @@map(\"voice_sessions\")\n}\n\n// =====================================================================\n// SKILLS (§6.7)\n// =====================================================================\n\nmodel Skill {\n  id              String       @id @default(uuid())\n  organization_id String? // null = platform starter skill\n  owner_id        String?\n  name            String\n  emoji           String?\n  slug            String // \"/client-onboarding\"\n  description     String\n  instructions    String\n  /// Questions to ask first: [{ key, question, required }]\n  questions       Json         @default(\"[]\")\n  /// Tools and connections needed: [{ service_key, tools? }]\n  required_tools  Json         @default(\"[]\")\n  result          String?\n  sharing_level   SharingLevel @default(PRIVATE)\n  is_starter      Boolean      @default(false)\n  starter_key     String?      @unique\n  imported_from   String?\n  current_version Int          @default(1)\n  deleted_at      DateTime?\n  created_at      DateTime     @default(now())\n  updated_at      DateTime     @updatedAt\n\n  organization Organization?              @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  owner        User?                      @relation(\"SkillOwner\", fields: [owner_id], references: [id], onDelete: SetNull)\n  versions     SkillVersion[]\n  shares       SkillShare[]\n  files        SkillFile[]\n  bots         BotSkill[]\n  templates    BotTemplateSkill[]\n  runs         Run[]\n  run_steps    RunStep[]\n  mentions     MessageMention[]\n  automations  Automation[]\n  starter_orgs OrganizationStarterSkill[]\n\n  @@unique([organization_id, slug])\n  @@index([organization_id, sharing_level])\n  @@index([owner_id])\n  @@index([is_starter])\n  @@index([deleted_at])\n  @@map(\"skills\")\n}\n\n/// Every change creates a version; earlier versions can be viewed and restored.\nmodel SkillVersion {\n  id                    String   @id @default(uuid())\n  skill_id              String\n  version               Int\n  name                  String\n  emoji                 String?\n  description           String\n  instructions          String\n  questions             Json\n  required_tools        Json\n  result                String?\n  change_summary        String?\n  created_by_id         String?\n  restored_from_version Int?\n  created_at            DateTime @default(now())\n\n  skill      Skill @relation(fields: [skill_id], references: [id], onDelete: Cascade)\n  created_by User? @relation(fields: [created_by_id], references: [id], onDelete: SetNull)\n\n  @@unique([skill_id, version])\n  @@index([created_by_id])\n  @@map(\"skill_versions\")\n}\n\nmodel SkillShare {\n  id         String    @id @default(uuid())\n  skill_id   String\n  user_id    String\n  role       SkillRole @default(USER)\n  created_at DateTime  @default(now())\n\n  skill Skill @relation(fields: [skill_id], references: [id], onDelete: Cascade)\n  user  User  @relation(fields: [user_id], references: [id], onDelete: Cascade)\n\n  @@unique([skill_id, user_id])\n  @@index([user_id])\n  @@map(\"skill_shares\")\n}\n\nmodel SkillFile {\n  skill_id   String\n  file_id    String\n  created_at DateTime @default(now())\n\n  skill Skill @relation(fields: [skill_id], references: [id], onDelete: Cascade)\n  file  File  @relation(fields: [file_id], references: [id], onDelete: Cascade)\n\n  @@id([skill_id, file_id])\n  @@index([file_id])\n  @@map(\"skill_files\")\n}\n\n/// §13.4 Skills — which starter skills an organisation shows its members.\nmodel OrganizationStarterSkill {\n  organization_id String\n  skill_id        String\n  enabled         Boolean @default(true)\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  skill        Skill        @relation(fields: [skill_id], references: [id], onDelete: Cascade)\n\n  @@id([organization_id, skill_id])\n  @@index([skill_id])\n  @@map(\"organization_starter_skills\")\n}\n\n// =====================================================================\n// ARTIFACTS (§7.5)\n// =====================================================================\n\nmodel Artifact {\n  id                     String               @id @default(uuid())\n  organization_id        String\n  owner_id               String?\n  conversation_id        String?\n  message_id             String?\n  duplicated_from_id     String?\n  title                  String\n  slug                   String // readable link \".../a/q4-webinar\"\n  type                   ArtifactType         @default(OTHER)\n  description            String?\n  sharing_level          ArtifactSharingLevel @default(PRIVATE)\n  // Public link\n  public_enabled         Boolean              @default(false)\n  public_password_hash   String?\n  public_expires_at      DateTime?\n  allow_search_engines   Boolean              @default(false)\n  allow_embedding        Boolean              @default(true)\n  public_ai_enabled      Boolean              @default(true)\n  public_uploads_enabled Boolean              @default(true)\n  // Publishing\n  review_before_publish  Boolean              @default(false)\n  current_version_id     String?              @unique\n  draft_version_id       String?              @unique\n  // Stats\n  view_count             Int                  @default(0)\n  use_count              Int                  @default(0)\n  is_pinned_by           Json? // { userId: true } — per-user pins; kept small\n  taken_down_at          DateTime?\n  deleted_at             DateTime?\n  created_at             DateTime             @default(now())\n  updated_at             DateTime             @updatedAt\n\n  organization    Organization        @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  owner           User?               @relation(\"ArtifactOwner\", fields: [owner_id], references: [id], onDelete: SetNull)\n  conversation    Conversation?       @relation(fields: [conversation_id], references: [id], onDelete: SetNull)\n  message         Message?            @relation(fields: [message_id], references: [id], onDelete: SetNull)\n  duplicated_from Artifact?           @relation(\"ArtifactDuplicate\", fields: [duplicated_from_id], references: [id], onDelete: SetNull)\n  duplicates      Artifact[]          @relation(\"ArtifactDuplicate\")\n  current_version ArtifactVersion?    @relation(\"ArtifactCurrentVersion\", fields: [current_version_id], references: [id], onDelete: SetNull)\n  draft_version   ArtifactVersion?    @relation(\"ArtifactDraftVersion\", fields: [draft_version_id], references: [id], onDelete: SetNull)\n  versions        ArtifactVersion[]   @relation(\"ArtifactVersions\")\n  shares          ArtifactShare[]\n  comments        ArtifactComment[]\n  records         ArtifactRecord[]\n  reports         ArtifactReport[]\n  files           File[]\n  data_grants     ArtifactDataGrant[]\n\n  @@unique([organization_id, slug])\n  @@index([organization_id, sharing_level])\n  @@index([owner_id])\n  @@index([conversation_id])\n  @@index([message_id])\n  @@index([duplicated_from_id])\n  @@index([public_enabled])\n  @@index([deleted_at])\n  @@map(\"artifacts\")\n}\n\n/// Immutable published build per version, stored at artifacts/<artifactId>/<versionId>/ in the artifacts bucket.\nmodel ArtifactVersion {\n  id                    String                @id @default(uuid())\n  artifact_id           String\n  version               Int\n  status                ArtifactVersionStatus @default(PUBLISHED)\n  label                 String? // \"Sent to client\"\n  change_summary        String?\n  /// Source (React + shadcn) for editing / diffing.\n  source                Json\n  bundle_path           String?\n  created_by_id         String?\n  run_id                String?\n  restored_from_version Int?\n  published_at          DateTime?\n  created_at            DateTime              @default(now())\n\n  artifact   Artifact  @relation(\"ArtifactVersions\", fields: [artifact_id], references: [id], onDelete: Cascade)\n  created_by User?     @relation(fields: [created_by_id], references: [id], onDelete: SetNull)\n  run        Run?      @relation(fields: [run_id], references: [id], onDelete: SetNull)\n  current_of Artifact? @relation(\"ArtifactCurrentVersion\")\n  draft_of   Artifact? @relation(\"ArtifactDraftVersion\")\n\n  @@unique([artifact_id, version])\n  @@index([created_by_id])\n  @@index([run_id])\n  @@map(\"artifact_versions\")\n}\n\n/// Per-member role, or organisation-wide role when user_id is null.\nmodel ArtifactShare {\n  id          String       @id @default(uuid())\n  artifact_id String\n  user_id     String?\n  role        ArtifactRole @default(VIEWER)\n  created_at  DateTime     @default(now())\n\n  artifact Artifact @relation(fields: [artifact_id], references: [id], onDelete: Cascade)\n  user     User?    @relation(fields: [user_id], references: [id], onDelete: Cascade)\n\n  @@unique([artifact_id, user_id])\n  @@index([user_id])\n  @@map(\"artifact_shares\")\n}\n\nmodel ArtifactComment {\n  id                String    @id @default(uuid())\n  artifact_id       String\n  author_id         String?\n  parent_comment_id String?\n  /// Where in the artifact (element selector / version anchor).\n  anchor            Json?\n  content           String\n  mentioned_bot_id  String?\n  resolved_at       DateTime?\n  deleted_at        DateTime?\n  created_at        DateTime  @default(now())\n  updated_at        DateTime  @updatedAt\n\n  artifact      Artifact          @relation(fields: [artifact_id], references: [id], onDelete: Cascade)\n  author        User?             @relation(fields: [author_id], references: [id], onDelete: SetNull)\n  parent        ArtifactComment?  @relation(\"ArtifactCommentThread\", fields: [parent_comment_id], references: [id], onDelete: Cascade)\n  replies       ArtifactComment[] @relation(\"ArtifactCommentThread\")\n  mentioned_bot Bot?              @relation(\"ArtifactCommentBotMention\", fields: [mentioned_bot_id], references: [id], onDelete: SetNull)\n\n  @@index([artifact_id, created_at])\n  @@index([author_id])\n  @@index([parent_comment_id])\n  @@index([mentioned_bot_id])\n  @@map(\"artifact_comments\")\n}\n\n/// §7.5 \"Save information\" — stored data entered by visitors/members (form responses, votes, tracker items).\nmodel ArtifactRecord {\n  id              String    @id @default(uuid())\n  artifact_id     String\n  collection      String\n  data            Json\n  submitted_by_id String? // null for public visitors\n  visitor_id      String? // anonymous visitor cookie id\n  deleted_at      DateTime?\n  created_at      DateTime  @default(now())\n  updated_at      DateTime  @updatedAt\n\n  artifact Artifact @relation(fields: [artifact_id], references: [id], onDelete: Cascade)\n\n  @@index([artifact_id, collection])\n  @@index([submitted_by_id])\n  @@map(\"artifact_records\")\n}\n\n/// §7.5 \"Show live data\": a member allowed this artifact to read one connected service with their own access.\nmodel ArtifactDataGrant {\n  id          String   @id @default(uuid())\n  artifact_id String\n  user_id     String\n  service_key String // Composio toolkit slug, e.g. \"hubspot\"\n  created_at  DateTime @default(now())\n\n  artifact Artifact @relation(fields: [artifact_id], references: [id], onDelete: Cascade)\n  user     User     @relation(fields: [user_id], references: [id], onDelete: Cascade)\n\n  @@unique([artifact_id, user_id, service_key])\n  @@index([user_id])\n  @@map(\"artifact_data_grants\")\n}\n\nmodel ArtifactReport {\n  id             String               @id @default(uuid())\n  artifact_id    String\n  reporter_id    String?\n  reporter_email String?\n  reason         String\n  status         ArtifactReportStatus @default(OPEN)\n  reviewed_at    DateTime?\n  created_at     DateTime             @default(now())\n\n  artifact Artifact @relation(fields: [artifact_id], references: [id], onDelete: Cascade)\n  reporter User?    @relation(fields: [reporter_id], references: [id], onDelete: SetNull)\n\n  @@index([artifact_id, status])\n  @@index([reporter_id])\n  @@map(\"artifact_reports\")\n}\n\n// =====================================================================\n// CONNECTIONS, CREDENTIALS, TOOL SERVERS (§8)\n// =====================================================================\n\n/// A linked account. COMPOSIO rows hold only the Composio connected-account ID; API_KEY/MCP rows point to a Credential.\nmodel Connection {\n  id                            String           @id @default(uuid())\n  organization_id               String\n  owner_id                      String? // null when shared and owner left\n  kind                          ConnectionKind\n  service_key                   String // \"gmail\", \"hubspot\", \"mailchimp\"…\n  service_name                  String\n  label                         String // \"Gmail – Sales\"\n  account_identifier            String? // email / username shown in the UI\n  visibility                    Visibility       @default(PRIVATE)\n  restricted_to_bots            Boolean          @default(false)\n  status                        ConnectionStatus @default(ACTIVE)\n  status_message                String?\n  composio_connected_account_id String?          @unique\n  composio_auth_config_id       String?\n  /// The Composio user the account was linked under. Tool calls must send exactly this — it is stored, never\n  /// recomputed, because it depends on NODE_ENV and visibility at connect time.\n  composio_user_id              String?\n  credential_id                 String?          @unique\n  tool_server_id                String?          @unique\n  last_synced_at                DateTime?\n  last_used_at                  DateTime?\n  deleted_at                    DateTime?\n  created_at                    DateTime         @default(now())\n  updated_at                    DateTime         @updatedAt\n\n  organization          Organization                    @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  owner                 User?                           @relation(\"ConnectionOwner\", fields: [owner_id], references: [id], onDelete: SetNull)\n  credential            Credential?                     @relation(fields: [credential_id], references: [id], onDelete: SetNull)\n  tool_server           ToolServer?                     @relation(fields: [tool_server_id], references: [id], onDelete: SetNull)\n  bot_connections       BotConnection[]\n  bot_restrictions      ConnectionBotRestriction[]\n  run_steps             RunStep[]\n  automation_links      AutomationConnection[]\n  pre_approvals         AutomationPreApproval[]\n  result_destinations   AutomationResultDestination[]\n  transfers             ComputerTransfer[]\n  activity_logs         ActivityLog[]\n  user_defaults         UserServiceDefault[]\n  trigger_subscriptions AutomationTriggerSubscription[]\n\n  @@index([organization_id, visibility, status])\n  @@index([owner_id])\n  @@index([service_key])\n  @@index([deleted_at])\n  @@map(\"connections\")\n}\n\n/// §8.3 — a shared connection \"limited to specific bots\".\nmodel ConnectionBotRestriction {\n  connection_id String\n  bot_id        String\n  created_at    DateTime @default(now())\n\n  connection Connection @relation(fields: [connection_id], references: [id], onDelete: Cascade)\n  bot        Bot        @relation(fields: [bot_id], references: [id], onDelete: Cascade)\n\n  @@id([connection_id, bot_id])\n  @@index([bot_id])\n  @@map(\"connection_bot_restrictions\")\n}\n\n/// §8.7 / §8.9 — credential METADATA only. The value lives in Secret Manager as `cred-<id>`.\nmodel Credential {\n  id                   String              @id @default(uuid())\n  organization_id      String\n  owner_type           CredentialOwnerType @default(USER)\n  owner_id             String?\n  kind                 CredentialKind\n  label                String\n  service_key          String?\n  service_name         String?\n  visibility           Visibility          @default(PRIVATE)\n  status               CredentialStatus    @default(ACTIVE)\n  masked_hint          String? // \"…a9f2\"\n  /// WEBSITE_LOGIN only: the site (and its subdomains) the login may be typed into, e.g. \"portal.acme.com\".\n  website_domain       String?\n  expires_at           DateTime?\n  scope                String?\n  secret_resource_name String              @unique // projects/<p>/secrets/cred-<id>\n  secret_version       String?\n  last_tested_at       DateTime?\n  last_used_at         DateTime?\n  last_used_bot_id     String?\n  deleted_at           DateTime?\n  created_at           DateTime            @default(now())\n  updated_at           DateTime            @updatedAt\n\n  organization  Organization      @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  owner         User?             @relation(\"CredentialOwner\", fields: [owner_id], references: [id], onDelete: SetNull)\n  last_used_bot Bot?              @relation(\"CredentialLastUsedBot\", fields: [last_used_bot_id], references: [id], onDelete: SetNull)\n  connection    Connection?\n  tool_server   ToolServer?\n  bots          BotCredential[]\n  events        CredentialEvent[]\n\n  @@index([organization_id, visibility, status])\n  @@index([owner_id])\n  @@index([last_used_bot_id])\n  @@index([deleted_at])\n  @@map(\"credentials\")\n}\n\n/// §8.9 \"History\" — every lifecycle event and every use. Values never recorded.\nmodel CredentialEvent {\n  id            String              @id @default(uuid())\n  credential_id String\n  type          CredentialEventType\n  actor_user_id String?\n  actor_bot_id  String?\n  run_id        String?\n  action        String?\n  metadata      Json?\n  created_at    DateTime            @default(now())\n\n  credential Credential @relation(fields: [credential_id], references: [id], onDelete: Cascade)\n  actor_user User?      @relation(fields: [actor_user_id], references: [id], onDelete: SetNull)\n\n  @@index([credential_id, created_at])\n  @@index([actor_user_id])\n  @@index([actor_bot_id])\n  @@map(\"credential_events\")\n}\n\n/// §8.4 — custom MCP tool server. Tools are listed from the server and cached in Redis.\nmodel ToolServer {\n  id              String             @id @default(uuid())\n  organization_id String\n  owner_id        String?\n  name            String\n  url             String\n  auth_kind       ToolServerAuthKind @default(NONE)\n  credential_id   String?            @unique\n  visibility      Visibility         @default(PRIVATE)\n  status          ToolServerStatus   @default(ACTIVE)\n  status_message  String?\n  tool_count      Int                @default(0)\n  last_listed_at  DateTime?\n  deleted_at      DateTime?\n  created_at      DateTime           @default(now())\n  updated_at      DateTime           @updatedAt\n\n  organization Organization    @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  owner        User?           @relation(\"ToolServerOwner\", fields: [owner_id], references: [id], onDelete: SetNull)\n  credential   Credential?     @relation(fields: [credential_id], references: [id], onDelete: SetNull)\n  connection   Connection?\n  bots         BotToolServer[]\n\n  @@index([organization_id, visibility])\n  @@index([owner_id])\n  @@index([deleted_at])\n  @@map(\"tool_servers\")\n}\n\n// =====================================================================\n// FILES (§7.7)\n// =====================================================================\n\nmodel File {\n  id                  String     @id @default(uuid())\n  organization_id     String?\n  uploaded_by_id      String?\n  bucket              FileBucket\n  area                FileArea\n  object_path         String     @unique // orgs/<orgId>/<area>/<fileId>\n  filename            String\n  mimetype            String\n  size                BigInt\n  status              FileStatus @default(PENDING)\n  checksum            String?\n  // Parent record (at most one set)\n  conversation_id     String?\n  bot_id              String?\n  skill_id            String?\n  artifact_id         String?\n  automation_id       String?\n  run_id              String?\n  computer_session_id String?\n  is_public_upload    Boolean    @default(false)\n  visitor_id          String?\n  deleted_at          DateTime?\n  purge_after         DateTime?\n  expires_at          DateTime? // exports: 7 days\n  created_at          DateTime   @default(now())\n  updated_at          DateTime   @updatedAt\n\n  organization     Organization?      @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  uploaded_by      User?              @relation(\"FileUploader\", fields: [uploaded_by_id], references: [id], onDelete: SetNull)\n  conversation     Conversation?      @relation(fields: [conversation_id], references: [id], onDelete: Cascade)\n  skill            SkillFile[]\n  artifact         Artifact?          @relation(fields: [artifact_id], references: [id], onDelete: Cascade)\n  automation       Automation?        @relation(fields: [automation_id], references: [id], onDelete: Cascade)\n  run              Run?               @relation(fields: [run_id], references: [id], onDelete: SetNull)\n  computer_session ComputerSession?   @relation(\"ComputerSessionFiles\", fields: [computer_session_id], references: [id], onDelete: SetNull)\n  messages         MessageFile[]\n  knowledge_item   KnowledgeItem?\n  user_avatar      User?              @relation(\"UserAvatar\")\n  org_logo         Organization?      @relation(\"OrganizationLogo\")\n  bot_image        Bot?               @relation(\"BotImage\")\n  replay_of        ComputerSession?   @relation(\"ComputerSessionReplay\")\n  export           DataExport?\n  transfers        ComputerTransfer[]\n\n  @@index([organization_id, area])\n  @@index([uploaded_by_id])\n  @@index([conversation_id])\n  @@index([bot_id])\n  @@index([skill_id])\n  @@index([artifact_id])\n  @@index([automation_id])\n  @@index([run_id])\n  @@index([computer_session_id])\n  @@index([status])\n  @@index([deleted_at, purge_after])\n  @@index([expires_at])\n  @@map(\"files\")\n}\n\n// =====================================================================\n// CLOUD COMPUTERS (§9)\n// =====================================================================\n\n/// One Daytona sandbox per bot (when enabled). Idle-pause job ID = computer-idle:<botId>.\nmodel CloudComputer {\n  id                  String              @id @default(uuid())\n  organization_id     String\n  bot_id              String              @unique\n  daytona_sandbox_id  String?             @unique\n  status              CloudComputerStatus @default(OFF)\n  status_message      String?\n  storage_used_bytes  BigInt              @default(0)\n  storage_limit_bytes BigInt?\n  last_active_at      DateTime?\n  paused_at           DateTime?\n  session_started_at  DateTime?\n  total_minutes       Int                 @default(0)\n  created_at          DateTime            @default(now())\n  updated_at          DateTime            @updatedAt\n\n  organization       Organization       @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  bot                Bot                @relation(fields: [bot_id], references: [id], onDelete: Cascade)\n  sessions           ComputerSession[]\n  signed_in_websites SignedInWebsite[]\n  transfers          ComputerTransfer[]\n\n  @@index([organization_id, status])\n  @@map(\"cloud_computers\")\n}\n\n/// A period of use: a bot run, or a user exploring manually. Replay is a File in the replays bucket.\nmodel ComputerSession {\n  id                String              @id @default(uuid())\n  cloud_computer_id String\n  kind              ComputerSessionKind\n  run_id            String?\n  user_id           String? // who explored / took control\n  started_at        DateTime            @default(now())\n  ended_at          DateTime?\n  minutes           Int                 @default(0)\n  replay_file_id    String?             @unique\n  /// [{ from, to, reason: \"take_control\" | \"secure_sign_in\" }] — hidden in replay (§9.4)\n  hidden_ranges     Json?\n  control_events    Json? // [{ at, event: \"take_control\" | \"hand_back\" }]\n  created_at        DateTime            @default(now())\n\n  cloud_computer CloudComputer @relation(fields: [cloud_computer_id], references: [id], onDelete: Cascade)\n  run            Run?          @relation(fields: [run_id], references: [id], onDelete: SetNull)\n  user           User?         @relation(fields: [user_id], references: [id], onDelete: SetNull)\n  replay_file    File?         @relation(\"ComputerSessionReplay\", fields: [replay_file_id], references: [id], onDelete: SetNull)\n  files          File[]        @relation(\"ComputerSessionFiles\")\n\n  @@index([cloud_computer_id, started_at])\n  @@index([run_id])\n  @@index([user_id])\n  @@map(\"computer_sessions\")\n}\n\n/// §9.4 — websites the bot's browser profile is signed in to (from the cookie store, grouped by site).\nmodel SignedInWebsite {\n  id                String   @id @default(uuid())\n  cloud_computer_id String\n  domain            String\n  signed_in_at      DateTime @default(now())\n  last_seen_at      DateTime @default(now())\n\n  cloud_computer CloudComputer @relation(fields: [cloud_computer_id], references: [id], onDelete: Cascade)\n\n  @@unique([cloud_computer_id, domain])\n  @@map(\"signed_in_websites\")\n}\n\n/// §9.5 — every copy_to_computer / copy_from_computer, with connection, source, destination and size.\nmodel ComputerTransfer {\n  id                String             @id @default(uuid())\n  cloud_computer_id String\n  run_id            String?\n  direction         TransferDirection\n  source_kind       TransferSourceKind\n  connection_id     String?\n  file_id           String?\n  source            String // path, URL or tool reference (no tokens / signed URLs)\n  destination       String\n  size_bytes        BigInt             @default(0)\n  succeeded         Boolean            @default(true)\n  error             String?\n  created_at        DateTime           @default(now())\n\n  cloud_computer CloudComputer @relation(fields: [cloud_computer_id], references: [id], onDelete: Cascade)\n  run            Run?          @relation(fields: [run_id], references: [id], onDelete: SetNull)\n  connection     Connection?   @relation(fields: [connection_id], references: [id], onDelete: SetNull)\n  file           File?         @relation(fields: [file_id], references: [id], onDelete: SetNull)\n\n  @@index([cloud_computer_id, created_at])\n  @@index([run_id])\n  @@index([connection_id])\n  @@index([file_id])\n  @@map(\"computer_transfers\")\n}\n\n// =====================================================================\n// AUTOMATIONS (§10)\n// =====================================================================\n\nmodel Automation {\n  id                         String                @id @default(uuid())\n  organization_id            String\n  owner_id                   String\n  bot_id                     String\n  name                       String\n  instructions               String\n  skill_id                   String?\n  trigger_kind               AutomationTriggerKind\n  cron_expression            String?\n  timezone                   String?\n  device_place_id            String?\n  place_event                String? // \"arrive\" | \"leave\"\n  uses_cloud_computer        Boolean               @default(false)\n  status                     AutomationStatus      @default(ACTIVE)\n  status_reason              String?\n  source_conversation_id     String?\n  results_conversation_id    String?\n  /// Notes memory (JSON, max 1 MB). Files live in Cloud Storage under automations/<id>/.\n  memory_notes               Json?\n  memory_plan                String? // what the bot said it would remember\n  consecutive_failures       Int                   @default(0)\n  next_run_at                DateTime?\n  last_run_at                DateTime?\n  run_count                  Int                   @default(0)\n  pre_approvals_confirmed_at DateTime?\n  deleted_at                 DateTime?\n  created_at                 DateTime              @default(now())\n  updated_at                 DateTime              @updatedAt\n\n  organization          Organization                    @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  owner                 User                            @relation(fields: [owner_id], references: [id], onDelete: Cascade)\n  bot                   Bot                             @relation(fields: [bot_id], references: [id], onDelete: Cascade)\n  skill                 Skill?                          @relation(fields: [skill_id], references: [id], onDelete: SetNull)\n  device_place          DevicePlace?                    @relation(fields: [device_place_id], references: [id], onDelete: SetNull)\n  source_conversation   Conversation?                   @relation(\"AutomationSourceConversation\", fields: [source_conversation_id], references: [id], onDelete: SetNull)\n  results_conversation  Conversation?                   @relation(\"AutomationResultConversation\", fields: [results_conversation_id], references: [id], onDelete: SetNull)\n  connections           AutomationConnection[]\n  pre_approvals         AutomationPreApproval[]\n  result_destinations   AutomationResultDestination[]\n  trigger_subscriptions AutomationTriggerSubscription[]\n  runs                  AutomationRun[]\n  files                 File[]\n\n  @@index([organization_id, status])\n  @@index([owner_id])\n  @@index([bot_id])\n  @@index([skill_id])\n  @@index([device_place_id])\n  @@index([source_conversation_id])\n  @@index([results_conversation_id])\n  @@index([next_run_at])\n  @@index([deleted_at])\n  @@map(\"automations\")\n}\n\nmodel AutomationConnection {\n  automation_id String\n  connection_id String\n\n  automation Automation @relation(fields: [automation_id], references: [id], onDelete: Cascade)\n  connection Connection @relation(fields: [connection_id], references: [id], onDelete: Cascade)\n\n  @@id([automation_id, connection_id])\n  @@index([connection_id])\n  @@map(\"automation_connections\")\n}\n\n/// §10.3 — { action_type, connection_id, target }, e.g. { SEND_MESSAGE, slack-company, \"channel:#y\" }.\nmodel AutomationPreApproval {\n  id            String     @id @default(uuid())\n  automation_id String\n  action_type   ActionType\n  connection_id String?\n  target        String\n  created_at    DateTime   @default(now())\n\n  automation Automation  @relation(fields: [automation_id], references: [id], onDelete: Cascade)\n  connection Connection? @relation(fields: [connection_id], references: [id], onDelete: Cascade)\n\n  @@unique([automation_id, action_type, connection_id, target])\n  @@index([connection_id])\n  @@map(\"automation_pre_approvals\")\n}\n\nmodel AutomationResultDestination {\n  id              String                @id @default(uuid())\n  automation_id   String\n  kind            ResultDestinationKind\n  conversation_id String?\n  email           String?\n  connection_id   String?\n  target          String? // e.g. \"channel:#security\"\n\n  automation Automation  @relation(fields: [automation_id], references: [id], onDelete: Cascade)\n  connection Connection? @relation(fields: [connection_id], references: [id], onDelete: SetNull)\n\n  @@index([automation_id])\n  @@index([connection_id])\n  @@map(\"automation_result_destinations\")\n}\n\n/// Composio trigger subscription for triggered automations.\nmodel AutomationTriggerSubscription {\n  id                  String   @id @default(uuid())\n  automation_id       String\n  connection_id       String\n  trigger_key         String // e.g. \"HUBSPOT_NEW_DEAL\"\n  trigger_name        String? // \"New deal\", shown on the automation\n  composio_trigger_id String?  @unique\n  config              Json?\n  created_at          DateTime @default(now())\n\n  automation Automation @relation(fields: [automation_id], references: [id], onDelete: Cascade)\n  connection Connection @relation(fields: [connection_id], references: [id], onDelete: Cascade)\n\n  @@index([automation_id])\n  @@index([connection_id])\n  @@map(\"automation_trigger_subscriptions\")\n}\n\n/// §10.2 run history. Skipped ticks are recorded here without a Run.\nmodel AutomationRun {\n  id               String              @id @default(uuid())\n  automation_id    String\n  status           AutomationRunStatus @default(QUEUED)\n  attempt          Int                 @default(1)\n  is_retry         Boolean             @default(false)\n  trigger_event_id String?\n  /// §10.2: the event that started this run (trimmed), shown to the bot and in the run history.\n  trigger_event    Json?\n  scheduled_for    DateTime?\n  started_at       DateTime?\n  finished_at      DateTime?\n  duration_ms      Int?\n  result_summary   String?\n  error            String?\n  created_at       DateTime            @default(now())\n\n  automation Automation @relation(fields: [automation_id], references: [id], onDelete: Cascade)\n  run        Run?\n\n  @@index([automation_id, created_at])\n  @@index([status])\n  @@map(\"automation_runs\")\n}\n\n// =====================================================================\n// NOTIFICATIONS (§12)\n// =====================================================================\n\nmodel Notification {\n  id              String            @id @default(uuid())\n  organization_id String?\n  user_id         String\n  event           NotificationEvent\n  title           String\n  body            String?\n  link_path       String? // \"/c/<id>\", \"/approvals/<id>\"\n  data            Json?\n  is_urgent       Boolean           @default(false)\n  read_at         DateTime?\n  created_at      DateTime          @default(now())\n\n  organization Organization?          @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  user         User                   @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  deliveries   NotificationDelivery[]\n\n  @@index([user_id, read_at, created_at])\n  @@index([organization_id])\n  @@map(\"notifications\")\n}\n\nmodel NotificationDelivery {\n  id              String              @id @default(uuid())\n  notification_id String\n  channel         NotificationChannel\n  device_id       String?\n  status          DeliveryStatus      @default(QUEUED)\n  scheduled_for   DateTime? // delayed by quiet hours\n  sent_at         DateTime?\n  error           String?\n  attempts        Int                 @default(0)\n  created_at      DateTime            @default(now())\n\n  notification Notification @relation(fields: [notification_id], references: [id], onDelete: Cascade)\n  device       Device?      @relation(fields: [device_id], references: [id], onDelete: SetNull)\n\n  @@index([notification_id])\n  @@index([device_id])\n  @@index([status, scheduled_for])\n  @@map(\"notification_deliveries\")\n}\n\n// =====================================================================\n// USAGE, LIMITS, BILLING (§11, §13.4)\n// =====================================================================\n\n/// One row per charge (model call, voice session, computer minutes...). The only usage store: overview, limits, alerts and the Charges tab read it.\nmodel UsageCharge {\n  id              String    @id @default(uuid())\n  organization_id String\n  user_id         String?\n  bot_id          String?\n  model_id        String?\n  run_id          String?\n  kind            UsageKind\n  quantity        Decimal   @db.Decimal(18, 4) // tokens, minutes, bytes\n  input_tokens    Int?\n  output_tokens   Int?\n  cost            Decimal   @default(0) @db.Decimal(12, 6)\n  created_at      DateTime  @default(now())\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  user         User?        @relation(fields: [user_id], references: [id], onDelete: SetNull)\n  bot          Bot?         @relation(fields: [bot_id], references: [id], onDelete: SetNull)\n  model        AiModel?     @relation(fields: [model_id], references: [id], onDelete: SetNull)\n  run          Run?         @relation(fields: [run_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, created_at])\n  @@index([user_id])\n  @@index([bot_id])\n  @@index([model_id])\n  @@index([run_id])\n  @@map(\"usage_charges\")\n}\n\nmodel UsageLimit {\n  id              String          @id @default(uuid())\n  organization_id String\n  scope           UsageLimitScope\n  user_id         String? // MEMBER scope\n  bot_id          String? // BOT scope\n  monthly_limit   Decimal         @db.Decimal(12, 4)\n  created_at      DateTime        @default(now())\n  updated_at      DateTime        @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  bot          Bot?         @relation(fields: [bot_id], references: [id], onDelete: Cascade)\n\n  @@unique([organization_id, scope, user_id, bot_id])\n  @@index([user_id])\n  @@index([bot_id])\n  @@map(\"usage_limits\")\n}\n\nmodel UsageAlert {\n  id              String          @id @default(uuid())\n  organization_id String\n  scope           UsageLimitScope\n  user_id         String?\n  bot_id          String?\n  period          String\n  threshold       Int // 80 / 100\n  sent_at         DateTime        @default(now())\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@unique([organization_id, scope, user_id, bot_id, period, threshold])\n  @@map(\"usage_alerts\")\n}\n\nmodel Subscription {\n  id                     String             @id @default(uuid())\n  organization_id        String             @unique\n  plan                   PlanTier           @default(FREE)\n  status                 SubscriptionStatus @default(ACTIVE)\n  stripe_subscription_id String?            @unique\n  stripe_price_id        String?\n  seats                  Int                @default(1)\n  current_period_start   DateTime?\n  current_period_end     DateTime?\n  cancel_at              DateTime?\n  trial_ends_at          DateTime?\n  created_at             DateTime           @default(now())\n  updated_at             DateTime           @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@map(\"subscriptions\")\n}\n\nmodel Invoice {\n  id                String        @id @default(uuid())\n  organization_id   String\n  stripe_invoice_id String        @unique\n  number            String?\n  status            InvoiceStatus\n  currency          String        @default(\"eur\")\n  amount_due        Decimal       @db.Decimal(12, 2)\n  amount_paid       Decimal       @default(0) @db.Decimal(12, 2)\n  usage_amount      Decimal       @default(0) @db.Decimal(12, 2)\n  hosted_url        String?\n  pdf_url           String?\n  period_start      DateTime?\n  period_end        DateTime?\n  issued_at         DateTime?\n  paid_at           DateTime?\n  created_at        DateTime      @default(now())\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@index([organization_id, issued_at])\n  @@map(\"invoices\")\n}\n\n// =====================================================================\n// ACTIVITY HISTORY AND EXPORTS (§11, §13.4)\n// =====================================================================\n\n/// Every bot action and admin change: what, when, which account, on whose behalf. Secrets never appear.\nmodel ActivityLog {\n  id              String    @id @default(uuid())\n  organization_id String\n  actor_type      ActorType\n  actor_user_id   String?\n  actor_bot_id    String?\n  on_behalf_of_id String?\n  action          String // \"message.sent\", \"connection.used\", \"member.role_changed\", \"secret.used\", \"device_tool.used\"…\n  target_type     String?\n  target_id       String?\n  connection_id   String?\n  run_id          String?\n  device_id       String?\n  metadata        Json?\n  ip_address      String?\n  created_at      DateTime  @default(now())\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  actor_user   User?        @relation(fields: [actor_user_id], references: [id], onDelete: SetNull)\n  actor_bot    Bot?         @relation(fields: [actor_bot_id], references: [id], onDelete: SetNull)\n  connection   Connection?  @relation(fields: [connection_id], references: [id], onDelete: SetNull)\n  run          Run?         @relation(fields: [run_id], references: [id], onDelete: SetNull)\n  device       Device?      @relation(fields: [device_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, created_at])\n  @@index([organization_id, action])\n  @@index([actor_user_id])\n  @@index([actor_bot_id])\n  @@index([on_behalf_of_id])\n  @@index([target_type, target_id])\n  @@index([connection_id])\n  @@index([run_id])\n  @@index([device_id])\n  @@map(\"activity_logs\")\n}\n\n/// \"Export my data\", activity exports and skill exports. Files expire after 7 days.\nmodel DataExport {\n  id              String       @id @default(uuid())\n  organization_id String?\n  user_id         String\n  kind            ExportKind\n  status          ExportStatus @default(QUEUED)\n  params          Json?\n  file_id         String?      @unique\n  error           String?\n  expires_at      DateTime?\n  completed_at    DateTime?\n  created_at      DateTime     @default(now())\n  updated_at      DateTime     @updatedAt\n\n  organization Organization? @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  user         User          @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  file         File?         @relation(fields: [file_id], references: [id], onDelete: SetNull)\n\n  @@index([user_id, created_at])\n  @@index([organization_id])\n  @@index([status])\n  @@map(\"data_exports\")\n}\n\n// =====================================================================\n// PLATFORM\n// =====================================================================\n\n/// DEV/STAGING ONLY fallback for §8.7 when Google Cloud Secret Manager is not available (SECRET_STORE=local-encrypted).\n/// Holds AES-256-GCM ciphertext keyed by the Secret Manager-style resource name. Never used when SECRET_STORE=gcp.\nmodel DevSecretBlob {\n  resource_name String   @id\n  version       Int      @default(1)\n  ciphertext    String\n  created_at    DateTime @default(now())\n  updated_at    DateTime @updatedAt\n\n  @@map(\"dev_secret_blobs\")\n}\n\n/// §14.1 — minimum supported app version per platform.\nmodel AppVersionPolicy {\n  platform        Platform @id\n  minimum_version String\n  latest_version  String?\n  update_url      String?\n  updated_at      DateTime @updatedAt\n\n  @@map(\"app_version_policies\")\n}\n\n/// A member's link between an outside channel and one bot (§16 Message from anywhere). Email works from the member's\n/// own address to their personal inbound address; Slack and WhatsApp are linked by sending the one-time code.\nmodel ChannelLink {\n  id                   String            @id @default(uuid())\n  organization_id      String\n  user_id              String\n  bot_id               String\n  channel              ExternalChannel\n  status               ChannelLinkStatus @default(PENDING)\n  /// Slack \"<team>:<user>\", WhatsApp phone number in E.164 digits; null for email (the member's account email is used).\n  external_id          String?\n  /// Email: the local part of the member's personal inbound address. Random, unguessable.\n  inbound_token        String?           @unique\n  /// One-time code the member sends from Slack / WhatsApp to finish linking.\n  link_code            String?           @unique\n  link_code_expires_at DateTime?\n  /// The direct conversation the channel's messages go to (created on first message).\n  conversation_id      String?\n  last_message_at      DateTime?\n  created_at           DateTime          @default(now())\n  updated_at           DateTime          @updatedAt\n\n  organization Organization  @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  user         User          @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  bot          Bot           @relation(fields: [bot_id], references: [id], onDelete: Cascade)\n  conversation Conversation? @relation(fields: [conversation_id], references: [id], onDelete: SetNull)\n\n  @@unique([organization_id, user_id, channel])\n  @@unique([channel, external_id])\n  @@index([bot_id])\n  @@index([user_id])\n  @@map(\"channel_links\")\n}\n"
}

